    static let uk: [String: String] = [
        "Settings": "Налаштування",
        "Keyboard shortcuts": "Сполучення клавіш",
        "Storage & models": "Сховище та моделі",
        "Asking is the one thing that leaves this Mac: your question, the search hits, and the transcripts the agent opens to answer go to %@ on your key. Nothing is sent until you ask.": "Запитання — єдине, що залишає цей Mac: ваше запитання, знайдені фрагменти та транскрипти, які агент відкриває для відповіді, йдуть до %@ на вашому ключі. Нічого не надсилається, поки ви не спитаєте.",
        "The Keychain refused to save the key — it stays in the field. Try again after unlocking the keychain.": "Keychain відмовився зберегти ключ — він залишився в полі. Розблокуйте в'язку і спробуйте ще раз.",
        "Couldn't reach the update server. Try again once you're online.": "Не вдалося зв'язатися з сервером оновлень. Спробуйте, коли з'явиться мережа.",
        "Update %@ is on its way — downloading now, it installs itself soon.": "Оновлення %@ вже в дорозі — завантажується і невдовзі встановиться саме.",
        "You're up to date — Dictate %@ is the newest version.": "У вас остання версія — новішої за Dictate %@ немає.",
        "Recorded meetings appear here.": "Записані зустрічі з'являться тут.",
        "This is your microphone only — the other side of the call was not recorded and cannot be recovered.": "Тут лише ваш мікрофон — друга сторона дзвінка не записувалась, і її не відновити.",
        "Turning both on covers the calls that come next.": "Якщо увімкнути обидва, наступні дзвінки буде записано повністю.",
        "%@ refused the request for billing reasons. Add credit in your provider account, or disconnect the agent in Settings.": "%@ відхилив запит через білінг. Поповніть рахунок у провайдера або відключіть агента в налаштуваннях.",
        "Agent": "Агент",
        "Ask your agent": "Запитати агента",
        "Ask your agent anything…": "Запитайте агента про будь-що…",
        "Has read %d of %d meetings": "Прочитав %d із %d зустрічей",
        "Has read 1 meeting": "Прочитав 1 зустріч",
        "Has read all %d meetings": "Прочитав усі %d зустрічей",
        "Meetings & Agent…": "Зустрічі та агент…",
        "Not now keeps the agent off and hidden. Search and transcripts are unaffected.": "«Не зараз» залишить агента вимкненим і прихованим. Пошук і транскрипти працюють як раніше.",
        "Nothing to read yet": "Поки нічого читати",
        "Off — has read nothing yet": "Вимкнений — ще нічого не прочитав",
        "Questions are never limited to one meeting. Your agent searches everything you have recorded and the answer names the meeting and the person.": "Запитання не обмежені однією зустріччю. Ваш агент шукає по всьому, що ви записали, і відповідь називає зустріч та людину.",
        "Reading %d of %d meetings…": "Читаю %d із %d зустрічей…",
        "The agent uses": "Агент відповідає через",
        "This is what writes the summary and the outline, and what gives your agent something to answer from. Off, you get the raw transcript — no summary, no outline, and no agent. Nothing is sent anywhere either way.": "Саме це пише резюме та зміст і дає агентові матеріал для відповідей. Вимкнено — залишається сирий транскрипт: ні резюме, ні змісту, ні агента. У будь-якому разі нікуди нічого не надсилається.",
        "Your agent answers questions across everything you have recorded — “what did we decide about the freeze date” — and cites the meeting and moment it came from. It needs the model that reads your meetings, which is currently off. Nothing leaves this Mac either way.": "Ваш агент відповідає на запитання по всьому, що ви записали, — «що ми вирішили щодо дати заморозки» — і називає зустріч та момент, звідки взято відповідь. Для цього потрібна модель, яка читає ваші зустрічі, а вона зараз вимкнена. У будь-якому разі з цього Mac нічого не йде.",
        "Your agent has nothing to read yet": "Вашому агентові поки нічого читати",
        "Your agent has read 1 meeting": "Ваш агент прочитав 1 зустріч",
        "Your agent has read all %d meetings": "Ваш агент прочитав усі %d зустрічей",
        "Your agent is off": "Ваш агент вимкнений",
        "Your agent is reading — %d of %d meetings so far": "Ваш агент читає — поки %d із %d зустрічей",
        "answers with %@": "відповідає через %@",
        "Nothing here can hear a call until it is granted in System Settings › Privacy & Security › Microphone.": "Ніщо тут не почує дзвінок, поки доступ не надано в System Settings › Privacy & Security › Microphone.",
        "There is no summary or outline — reading your meetings is off.": "Немає ні резюме, ні змісту — читання зустрічей вимкнене.",
        "This is your microphone only — the other side of the call is missing, the text is one unbroken block, and there is no summary or outline.": "Тут лише ваш мікрофон — другої сторони дзвінка немає, текст одним суцільним блоком, і немає ні резюме, ні змісту.",
        "Turn both on": "Увімкнути обидва",
        "Turn it on": "Увімкнути",
        "Turning it on also writes them for the recordings that come next. Writing one now leaves the switch off.": "Якщо увімкнути, вони будуть написані й для наступних записів. «Написати зараз» залишить перемикач вимкненим.",
        "Waiting on microphone access.": "Чекає на доступ до мікрофона.",
        "Waits for “%@” above — there is no call audio to separate yet.": "Чекає на «%@» вище — поки нічого розділяти, звук дзвінка не пишеться.",
        "Write one, this once": "Написати зараз, один раз",
        "Writing one now reads only this transcript and leaves the switches off. The other side of this call was not recorded and cannot be recovered.": "«Написати зараз» прочитає лише цей транскрипт і залишить перемикачі вимкненими. Друга сторона цього дзвінка не записувалась, і її не відновити.",
        "Writing…": "Пишу…",
        "macOS denied microphone access": "macOS відмовила в доступі до мікрофона",
        "%@ call — not being recorded": "Дзвінок у %@ — не записується",
        "Asked once. After this, the panel is the short version above.": "Запитується один раз. Далі панель буде короткою, як вище.",
        "Call recording is off, so this one is passing untranscribed. Turning it on gives you a searchable transcript and a summary afterwards, kept on this Mac.": "Запис дзвінків вимкнено, і цей минає без транскрипту. Якщо увімкнути, після дзвінка буде транскрипт із пошуком і резюме — усе зберігається на цьому Mac.",
        "Call — not being recorded": "Дзвінок — не записується",
        "Calls are not noticed automatically. You can start each one here, or let Dictate offer when a call begins.": "Дзвінки не помічаються автоматично. Можна запускати кожен тут — або дозволити Dictate пропонувати запис, коли дзвінок починається.",
        "Connect a provider…": "Підключити провайдера…",
        "Dictation still works. Each switch below says what it adds; you can turn on one and leave the rest alone.": "Диктування працює як раніше. Кожен перемикач нижче каже, що він додає; можна увімкнути один і не чіпати решту.",
        "Dictation works already — hold the dictation key and speak anywhere. Everything below is about meetings, and none of it is required. Turn on what you want; the rest stays off.": "Диктування вже працює — затисніть клавішу диктування і говоріть будь-де. Усе нижче — про зустрічі, і ніщо з цього не є обов'язковим. Увімкніть потрібне; решта залишиться вимкненою.",
        "Don't offer this again": "Більше не пропонувати",
        "Everything here is off, so calls pass unnoticed": "Тут усе вимкнено, і дзвінки минають непоміченими",
        "Let the model read your meetings": "Дозволити моделі читати ваші зустрічі",
        "Not watching for calls": "Дзвінки не відстежуються",
        "Notice when a call starts": "Помічати, коли починається дзвінок",
        "Off, a recording holds your microphone only — your half of the conversation, in one unbroken block. On, both sides are transcribed as named turns.": "Вимкнено — у записі лише ваш мікрофон: ваша половина розмови одним суцільним блоком. Увімкнено — обидві сторони розшифровуються як репліки з іменами.",
        "Off, you get only your own microphone — your half of the conversation. On, the other side is transcribed as well.": "Вимкнено — лише ваш мікрофон: ваша половина розмови. Увімкнено — розшифровується і друга сторона.",
        "On": "Увімк.",
        "Or leave this and set them up later in Settings.": "Або пропустіть — їх можна увімкнути пізніше в налаштуваннях.",
        "Read meeting names from Calendar": "Брати назви зустрічей із Календаря",
        "Record the call audio too": "Записувати і звук дзвінка",
        "Record the call audio, and separate the voices": "Записувати звук дзвінка та розділяти голоси",
        "Recordings arrive already titled instead of as “Zoom call, 14:02”. Only titles overlapping a recording are read.": "Записи з'являються вже з назвою, а не як «Дзвінок у Zoom, 14:02». Читаються лише події, що збігаються в часі із записом.",
        "Separate the voices": "Розділяти голоси",
        "Set up calls…": "Налаштувати дзвінки…",
