        "Turns one block of text into named turns, so you can see who committed to what. Names are yours to set and can be changed after the fact.": "Перетворює суцільний блок тексту на репліки з іменами, щоб було видно, хто що пообіцяв. Імена задаєте ви, і їх можна змінювати заднім числом.",
