        "Jump to newest": "До останніх",
        "Show in Finder": "Показати у Finder",
        "Rename this speaker": "Перейменувати спікера",
        "Name this speaker": "Як звати цього спікера?",
        "Name": "Ім'я",
        "Save": "Зберегти",
        "%d min": "%d хв",
        "%d s": "%d с",
        "System audio recording is not allowed. Enable Dictate in System Settings → Privacy & Security → Screen & System Audio Recording, then try again.": "Запис системного звуку не дозволено. Увімкніть Dictate у Системних параметрах → Конфіденційність і безпека → Запис екрана й системного звуку — і спробуйте ще раз.",
        "Stop": "Стоп",
        "Automatic (any language)": "Автоматично (будь-яка мова)",
        "detect while you speak": "визначається на ходу",
        "Search language…": "Пошук мови…",
        "Suggested": "Пропоновані",
        "No language matches your search.": "Нічого не знайдено.",
        "Translate key": "Клавіша перекладу",
        "%@ is using the microphone right now — close it and try again": "%@ зараз використовує мікрофон — закрий його та спробуй знову",
        "That was very quiet — move closer to the microphone": "Дуже тихо — присуньтеся ближче до мікрофона",
        "That was too loud — move back a little from the microphone": "Надто гучно — трохи відсуньтеся від мікрофона",
        "Sorry, I didn't catch that — could you say it again?": "Вибач, будь ласка, я тебе не розчув — міг би ти повторити?",
        "Not inserted — text copied, press ⌘V to paste": "Не вставлено — текст скопійовано, натисніть ⌘V",
        "Another app is using the microphone right now — close it and try again": "Мікрофон зараз використовує інший застосунок — закрий його та спробуй знову",
        "Shortcuts": "Клавіші",
        "General": "Загальні",
        "Status": "Стан",
        "Type a key…": "Натисніть клавішу…",
        "Hold to talk, release to insert what you said.": "Затисніть, щоб говорити; відпустіть — вставиться сказане.",
        "Version": "Версія",
        "Downloaded %d of %d MB": "Завантажено %d із %d МБ",
        "Preparing the model for the Neural Engine… A few minutes, one time.": "Підготовка моделі під Neural Engine… Кілька хвилин, один раз.",
        "Warming up the model…": "Розігріваю модель…",
        "Dictate is running from the downloaded image — drag it into Applications, eject the image, and launch it from there. Permissions granted to this temporary copy won't stick.": "Dictate запущено із завантаженого образу — перетягніть його в «Програми», витягніть образ і запустіть звідти. Дозволи, надані цій тимчасовій копії, не збережуться.",
        "Still stuck? Reset the permission — this clears the broken macOS record, then grant the fresh request.": "Досі не виходить? Скиньте дозвіл — це видалить зламаний запис macOS, потім надайте його в новому запиті.",
        "Words: %d · %.1f s": "Слів: %d · %.1f с",
        "Words: %d": "Слів: %d",
        "Cancelled": "Скасовано",
        "Changed your mind? Esc cancels the recording.": "Передумали? Esc скасовує запис.",
        "Network access: a one-time model download — nothing else. Don't take our word for it: turn off Wi-Fi and dictate.": "Мережа: разове завантаження моделі — і більше нічого. Не вірте на слово: вимкніть Wi-Fi і продиктуйте.",
        "About Dictate": "Про Dictate",
        "Welcome to Dictate": "Ласкаво просимо до Dictate",
        "Back": "Назад",
        "Next": "Далі",
        "Step %d of %d": "Крок %d з %d",
        "Dictation key": "Клавіша диктування",
        "This key types characters — they'll end up in your text while you hold it. A modifier (Option, Cmd, Shift, Ctrl) or an F-key is safer.": "Ця клавіша друкує символи — поки ви її тримаєте, вони потраплятимуть у текст. Надійніше обрати модифікатор (Option, Cmd, Shift, Ctrl) або F-клавішу.",
        "Microphone": "Мікрофон",
        "Accessibility": "Універсальний доступ (Accessibility)",
        "Dictate Settings": "Налаштування Dictate",
        "This key types characters — they'll go into the text during dictation. A modifier or F-key is better.": "Клавіша друкує символи — під час диктування вони потраплять у текст. Краще модифікатор або F-клавіша.",
        "Launch at login": "Запускати при вході в систему",
        "Show in Dock": "Показувати в Dock",
        "The agent searches and reads your transcripts on this Mac, and every answer names the meetings it drew from.": "Агент шукає та читає ваші транскрипти на цьому Mac, і кожна відповідь називає зустрічі, на які спирається.",
        "Undo remove": "Повернути ключ",
        "Call started": "Почався дзвінок",
        "Recording stopped by itself — the call ended.": "Запис зупинився сам — дзвінок завершився.",
        "Recording stopped by itself — ten minutes of silence.": "Запис зупинився сам — десять хвилин тиші.",
        "%@ call started": "Почався дзвінок у %@",
        "Not this one": "Не цей",
        "Record": "Записати",
        "Record this call": "Записати цей дзвінок",
        "Dictation that works offline — recognition runs entirely on this Mac.": "Диктування, що працює офлайн — розпізнавання цілком на цьому Mac.",
        "Translation that works offline — speak your language, another comes out.": "Переклад, що працює офлайн — говоріть своєю мовою, виходить інша.",
        "Meetings, recorded and structured: speakers, summary, outline, search.": "Зустрічі записані й структуровані: спікери, самарі, аутлайн, пошук.",
        "An optional agent that knows your meetings — answers quote the moment they came from.": "Опціональний агент, що знає ваші зустрічі, — відповіді цитують момент, звідки взяті.",
        "%d MB of %d MB": "%d МБ з %d МБ",
        "Already clicked and nothing changed?": "Натиснули, а нічого не змінилося?",
        "Applications": "Applications",
        "Downloading the speech model": "Завантажую модель розпізнавання",
        "Grant…": "Надати…",
        "Nothing here leaves this window. Two small things to try, then you are done.": "Звідси нічого не йде. Дві маленькі спроби — і все готово.",
        "Resume Download": "Продовжити завантаження",
        "Show me where to look": "Показати, куди дивитися",
        "Start Dictate when I log in — it appears in the Dock and the menu bar, and the Dock icon can be hidden later in Settings": "Запускати Dictate при вході в систему — він з’явиться в Dock і в рядку меню; іконку Dock можна сховати пізніше в налаштуваннях",
        "Start Using Dictate": "Почати користуватися Dictate",
        "Stopped · %d MB of %d MB kept on disk": "Зупинено · %d МБ з %d МБ збережено на диску",
        "The connection was interrupted. Resuming continues from where it stopped — you will not download the whole %d MB again.": "З’єднання перервалося. Продовження почнеться з того ж місця — всі %d МБ заново завантажувати не доведеться.",
        "The download stopped at %d MB": "Завантаження зупинилося на %d МБ",
        "The model is being compiled for your chip so recognition is fast later. This takes a minute on first launch and never happens again.": "Модель компілюється під ваш чип, щоб розпізнавання потім було швидким. Це займає хвилину при першому запуску і більше не повторюється.",
        "This happens once. The model stays on your Mac and is the reason dictation works without an internet connection afterwards.": "Це відбувається один раз. Модель залишається на вашому Mac — тому диктування потім працює без інтернету.",
        "To hear you. Audio is processed on this Mac and discarded.": "Щоб вас чути. Звук обробляється на цьому Mac і не зберігається.",
        "To type the recognized text into the app you are using. It is the only way an app can insert text elsewhere.": "Щоб вдруковувати розпізнаний текст у застосунок, де ви працюєте. Це єдиний спосіб, яким застосунок може вставляти текст в інші.",
        "Try it here first": "Спробуйте просто тут",
        "Two permissions from macOS": "Два дозволи від macOS",
        "macOS asks for these, not us. Dictate cannot work without both.": "Їх запитує macOS, не ми. Без обох Dictate працювати не може.",
        "Show or hide the conversations": "Показати або сховати розмови",
        "Show or hide the sidebar": "Показати або сховати бічну панель",
        "Show or hide the meeting list": "Показати або сховати список зустрічей",
        "Preparing the model for this Mac": "Готую модель для цього Mac",
        "Not ready yet — this takes a few seconds after launch. Keep holding %@ and it will start.": "Ще не готово — після запуску це займає кілька секунд. Тримайте %@, і все почнеться.",
        "Transcript text": "Текст транскрипту",
        "Smaller text": "Менший текст",
        "Standard text": "Стандартний текст",
        "Larger text": "Більший текст",
        "112 languages · from your system settings": "112 мов · із системних налаштувань",
        "Add tag": "Додати тег",
        "Appearance": "Оформлення",
        "Asked once. After this, recording starts from the menu bar without a prompt. Esc means don't record.": "Питаємо один раз. Далі запис починається з рядка меню без запитань. Esc — не записувати.",
        "Check for updates": "Перевірити оновлення",
        "Choose your keys and languages": "Виберіть клавіші та мови",
        "Click, then press a key": "Натисніть тут, потім клавішу",
        "Dark": "Темне",
        "Dictate stays dark even when macOS switches. Every surface follows: the window, the dictation overlay, the recording pill and the menu.": "Dictate лишається темним, навіть коли macOS перемикається. Слідують усі поверхні: вікно, оверлей диктування, пігулка запису та меню.",
        "Dictate stays light even when macOS switches. Every surface follows: the window, the dictation overlay, the recording pill and the menu.": "Dictate лишається світлим, навіть коли macOS перемикається. Слідують усі поверхні: вікно, оверлей диктування, пігулка запису та меню.",
        "Dictate will record your microphone and the audio from the call, and keep the transcript on this Mac. Recording other people may require their consent where you are.": "Dictate запише ваш мікрофон і звук дзвінка та збереже розшифровку на цьому Mac. Запис інших людей може потребувати їхньої згоди там, де ви є.",
        "Don't Record": "Не записувати",
        "Follows the macOS setting, switching with it at sunset. Choose Light or Dark to hold Dictate to one appearance regardless of the system.": "Слідує налаштуванню macOS і перемикається разом із ним із заходом сонця. Виберіть «Світле» або «Темне», щоб закріпити вигляд Dictate незалежно від системи.",
        "Hold the key while you speak. Anything can be changed later in Settings.": "Тримайте клавішу, поки говорите. Усе можна змінити пізніше в налаштуваннях.",
        "I speak": "Я розмовляю",
        "Light": "Світле",
        "Looking through %d meetings…": "Переглядаю %d зустрічей…",
        "Match system": "Як у системі",
        "Modifier keys work best: they never insert a character when you hold them. Esc always cancels a dictation in progress.": "Найкраще працюють клавіші-модифікатори: утримання не вводить символ. Esc завжди скасовує поточне диктування.",
        "Reading “%@”…": "Читаю «%@»…",
        "Record this call?": "Записати цей дзвінок?",
        "Searching your meetings…": "Шукаю у ваших зустрічах…",
        "Start Recording": "Почати запис",
        "Tags": "Теги",
        "Voices": "Голоси",
        "Summary": "Резюме",
        "Outline": "Зміст",
        "Hide outline": "Сховати зміст",
        "Show outline": "Показати зміст",
        "two levels": "два рівні",
        "three levels": "три рівні",
        "%d moments": "Моментів: %d",
        "Kept on this Mac. Deleting is immediate; beyond 50 conversations the oldest age out.": "Зберігається на цьому Mac. Видалення миттєве; після 50 бесід найстаріші витісняються.",
        "Ask across all meetings…": "Запитати по всіх зустрічах…",
        "Recently Added": "Нещодавно додані",
        "%d meetings · %d h of audio": "%d зустрічей · %d год аудіо",
        "%d meetings · %d min of audio": "%d зустрічей · %d хв аудіо",
        "Show more": "Показати повністю",
        "Try one of these": "Спробуйте щось із цього",
        "Accessibility access is turned off": "Доступ Accessibility вимкнено",
        "Dictation can hear you but cannot type. Re-enable it to continue.": "Диктування вас чує, але не може друкувати. Увімкніть доступ знову, щоб продовжити.",
        "Recent dictations": "Нещодавні диктування",
        "Secure input is active — the hotkey cannot work": "Увімкнено захищене введення — гаряча клавіша не може працювати",
        "Something has a password field focused. macOS does not say which app. Click into an ordinary text field and dictation works again.": "У якогось застосунку у фокусі поле пароля. macOS не каже, у якого. Клацніть у звичайне текстове поле — і диктування знову запрацює.",
        "Start Recording Meeting": "Записати зустріч",
        "Stop Recording Meeting": "Зупинити запис зустрічі",
        "click to copy": "клац — скопіювати",
        "dictate in %@": "диктування %@",
        "dictate in any language": "диктування будь-якою мовою",
        "translate %@ → %@": "переклад %@ → %@",
        "translate into %@": "переклад на %@",
        "%d waiting": "Очікує: %d",
        "%d words typed": "Надруковано слів: %d",
        "Add a Key…": "Додати ключ…",
        "Both will be inserted in the order you spoke them": "Обидві будуть вставлені в тому порядку, в якому ви їх сказали",
        "Check Audio Setup": "Перевірити налаштування звуку",
        "Clear All Filters": "Скинути всі фільтри",
        "F-keys can also trigger a system control (brightness, media) — macOS will do both. To use one as a plain key, turn on “Use F1, F2, etc. as standard function keys” in Keyboard settings.": "F-клавіші також керують системою (яскравість, медіа) — macOS зробить і те, й інше. Щоб використовувати її як звичайну клавішу, увімкніть «Use F1, F2, etc. as standard function keys» у налаштуваннях клавіатури.",
        "How this works": "Як це працює",
        "Input device changed": "Пристрій введення змінився",
        "Insert text by": "Вставляти текст",
        "It was revoked or replaced since you connected. It has been removed from the Keychain — nothing was retried with it.": "Його відкликано або замінено після підключення. Ключ видалено з В’язки ключів — з ним нічого не надсилалося повторно.",
        "Join a call in the browser, then start recording. Dictate captures your microphone and the call audio, transcribes both on this Mac, and keeps the transcript here. Nothing is uploaded.": "Почніть дзвінок у браузері й запустіть запис. Dictate записує ваш мікрофон і звук дзвінка, розпізнає обидва на цьому Mac і зберігає транскрипт тут. Нічого не завантажується в мережу.",
        "No meeting has all of these tags": "Жодна зустріч не має всіх цих тегів",
        "No meeting has this tag": "Жодна зустріч не має цього тега",
        "Nothing was said, or nothing was heard": "Нічого не було сказано — або нічого не було чути",
        "Only the unconfirmed tail is shown here — the rest is already in the document": "Тут видно лише непідтверджений хвіст — решта вже в документі",
        "Open Console": "Відкрити консоль",
        "Open Settings": "Відкрити налаштування",
        "Pasting is instant but replaces your clipboard for a moment. Typing works in apps that block paste, such as some terminals and remote desktops.": "Вставка миттєва, але на мить підмінює буфер обміну. Друк працює там, де вставку заблоковано — у деяких терміналах і віддалених робочих столах.",
        "Pasting it at once": "Вставкою одразу",
        "Recording ended here — this Mac went to sleep.": "Запис закінчився тут — Mac заснув.",
        "Remove “%@”": "Прибрати «%@»",
        "Return sends · Shift-Return adds a line · Esc clears": "Return — надіслати · Shift-Return — новий рядок · Esc — очистити",
        "Show Floating Timer": "Показати плаваючий таймер",
        "Start Recording a Meeting": "Записати зустріч",
        "Still recognizing the previous dictation": "Попередня диктовка ще розпізнається",
        "Still recognizing the previous dictation · %d words": "Попередня диктовка ще розпізнається · %d слів",
        "Switched to %@": "Перемкнено на %@",
        "Tag filters combine with “and” — a meeting must carry every selected tag to appear.": "Фільтри тегів поєднуються через «і» — зустріч має нести кожен вибраний тег.",
        "The answer stopped. Your question is kept above — retry when the connection returns. Search and transcripts still work.": "Відповідь перервалася. Ваше запитання збережено вище — повторіть, коли з’явиться зв’язок. Пошук і транскрипти працюють.",
        "The recording ran, but no speech was recognized on either side. Usually this means the call audio was never captured — a browser tab without audio permission, or the wrong output device.": "Запис тривав, але мовлення не розпізнано з жодного боку. Зазвичай це означає, що звук дзвінка не було захоплено — вкладка браузера без доступу до звуку або не той пристрій виводу.",
        "The saved key no longer works": "Збережений ключ більше не працює",
        "The switch stays off until it is granted in System Settings › Privacy & Security › Calendars. Only event titles that overlap a recording are ever read.": "Перемикач залишиться вимкненим, доки доступ не надано в System Settings › Privacy & Security › Calendars. Читаються лише назви подій, що перетинаються із записом.",
        "This Mac is offline": "Цей Mac офлайн",
        "Too many questions at once": "Забагато запитань одразу",
        "Typing as you speak": "Друкую, поки ви говорите",
        "Typing into %@ as you speak": "Друкую в %@, поки ви говорите",
        "Typing it out character by character": "Друком по літерах",
        "Your provider account is out of credit": "На рахунку провайдера закінчилися кредити",
        "Your provider is rate limiting. Wait a few seconds and retry — nothing was lost.": "Провайдер обмежує частоту запитів. Зачекайте кілька секунд і повторіть — нічого не втрачено.",
        "macOS denied calendar access": "macOS відмовила в доступі до календаря",
        "API key": "API-ключ",
        "All Meetings": "Усі зустрічі",
        "Assistant": "Асистент",
        "Checking the key with %@. No transcript is sent — only a test request.": "Перевіряємо ключ у %@. Транскрипти не надсилаються — лише тестовий запит.",
        "Closing the window does not stop the recording. Stop it here, or from the menu bar at any time.": "Закриття вікна не зупиняє запис. Зупиніть його тут або з меню-бара будь-коли.",
        "Connect an assistant to answer questions": "Підключіть асистента, щоб отримувати відповіді",
        "Dictate can record a browser call and keep the transcript on this Mac. Start one from the menu bar when your next call begins — you will be asked for consent once.": "Dictate може записати дзвінок у браузері й зберегти транскрипт на цьому Mac. Запустіть запис із меню-бара, коли почнеться наступний дзвінок — згоду спитаємо один раз.",
        "Done": "Готово",
        "Every change takes effect immediately.": "Кожна зміна застосовується одразу.",
        "Get one at %@.": "Отримати на %@.",
        "Hold a key, speak, let go. What you said is typed where your cursor is, in any app on this Mac.": "Затисніть клавішу, говоріть, відпустіть. Сказане буде надруковано там, де курсор, — у будь-якому застосунку на цьому Mac.",
        "Keys": "Клавіші",
        "Languages": "Мови",
        "Library": "Бібліотека",
        "Paste a key from your own account.": "Вставте ключ від власного акаунта.",
        "Saved to your Keychain, but not verified — this Mac is offline. It will be checked the first time you ask something.": "Збережено у В’язці ключів, але не перевірено — цей Mac офлайн. Перевіримо під час першого запитання.",
        "Set Up Dictate": "Налаштувати Dictate",
        "Stored in the macOS Keychain on this Mac. Never written to a settings file, never synced.": "Зберігається у В’язці ключів macOS на цьому Mac. Не записується у файли налаштувань, не синхронізується.",
        "The key was refused. It may be revoked, from a different provider, or out of credit — the key itself was not saved.": "Ключ відхилено. Можливо, його відкликано, він від іншого провайдера або без кредитів — сам ключ не збережено.",
