        "Translation data": "Дані перекладу",
        "The translate key transcribes your speech, then macOS translates it on this Mac. Picking a language may download its translation data once.": "Клавіша перекладу розпізнає вашу мову, а потім macOS перекладає її просто на цьому Mac. Під час вибору мови macOS може один раз завантажити її дані перекладу.",
        "Recognition runs on your Mac's Neural Engine — Whisper large-v3-turbo: 112 languages, great with accents, fast enough for live text. Translation runs on this Mac too. Your voice never leaves this computer.": "Розпізнавання працює на Neural Engine вашого Mac — Whisper large-v3-turbo: 112 мов, добре дає раду з акцентом і достатньо швидкий для живого тексту. Переклад теж відбувається на цьому Mac. Ваш голос не залишає цей комп’ютер.",
