        "The translate key transcribes your speech, then macOS translates it on this Mac. Picking a language may download its translation data once.": "La tecla de traducción transcribe tu voz y luego macOS la traduce en este Mac. Al elegir un idioma, macOS puede descargar sus datos de traducción una vez.",
        "Recognition runs on your Mac's Neural Engine — Whisper large-v3-turbo: 112 languages, great with accents, fast enough for live text. Translation runs on this Mac too. Your voice never leaves this computer.": "El reconocimiento se ejecuta en el Neural Engine de tu Mac: Whisper large-v3-turbo, 112 idiomas, se maneja bien con los acentos y es lo bastante rápido para el texto en vivo. La traducción también ocurre en este Mac. Tu voz nunca sale de este ordenador.",
        "Hold %@ and say it again — this time it comes out in %@.": "Mantén %@ y dilo otra vez: esta vez sale en %@.",
