        "Report an issue": "Comunicar um problema",
        "Finishing the transcript…": "A terminar a transcrição…",
        "Disk almost full — will stop to keep the transcript": "Disco quase cheio — vai parar para manter a transcrição",
        "Dictate is running from its disk image": "O Dictate está a ser executado a partir da imagem de disco",
        "Permissions granted from a disk image are lost as soon as it is ejected, and the model would download again every time. Move Dictate to your Applications folder first.": "As permissões concedidas a partir de uma imagem de disco perdem-se assim que esta é ejetada, e o modelo seria descarregado de novo de cada vez. Mova primeiro o Dictate para a pasta Aplicações.",
        "Move to Applications": "Mover para Aplicações",
        "Quit": "Sair",
        "Couldn't move Dictate automatically": "Não foi possível mover o Dictate automaticamente",
        "Drag Dictate from the disk image into the Applications folder, then launch it from there.": "Arraste o Dictate da imagem de disco para a pasta Aplicações e abra-o a partir daí.",
        "OK": "OK",
        "Inserted into %@": "Inserido em %@",
        "Inserted": "Inserido",
        "Accessibility is off — dictation can hear you but cannot type": "A Acessibilidade está desativada — o ditado ouve-o, mas não consegue escrever",
        "Open Privacy & Security…": "Abrir Privacidade e Segurança…",
        "1 dictation still being recognized": "1 ditado ainda a ser reconhecido",
        "%d dictations still being recognized": "%d ditados ainda a serem reconhecidos",
        "Language Packs…": "Pacotes de idioma…",
        "With this off, Dictate is menu-bar only. Clicking the Dock icon opens Meetings; the menu bar item is always there either way.":
            "Se estiver desativado, o Dictate vive apenas na barra de menus. Clicar no ícone da Dock abre Reuniões; o ícone da barra de menus está sempre presente.",
        "Language": "Idioma",
        "Interface language": "Idioma da interface",
        "Granted": "Concedida",
        "No": "Não",
        "Model ready": "Modelo pronto",
        "On-device recognition": "Reconhecimento no dispositivo",
        "Spoken language": "Idioma falado",
        "Download failed. Check your connection and retry.": "Falha no download. Verifique sua conexão e tente novamente.",
        "Not set": "Não definida",
        "Remove": "Remover",
        "Download & continue": "Baixar e continuar",
        "About %@ — downloaded once. This is the only time Dictate needs the internet.": "Cerca de %@ — baixado uma única vez. É o único momento em que o Dictate precisa de internet.",
        "Hold %@ and say something — the recognized text shows up below.": "Segure %@ e diga algo — o texto reconhecido aparece abaixo.",
        "Recognized text appears here…": "O texto reconhecido aparecerá aqui…",
        // Menu bar
        "Settings…": "Ajustes…",
        "Quit Dictate": "Encerrar Dictate",
        "Dictate — voice dictation": "Dictate — ditado por voz",
        // HUD
        "Recognizing…": "Reconhecendo…",
        "Esc to cancel": "Esc para cancelar",
        // Errors
        "Couldn't start recording: %@": "Não foi possível iniciar a gravação: %@",
        "Recording truncated at %d seconds (limit)": "Gravação cortada em %d segundos (limite)",
        "Audio device changed during recording — recording cancelled, please try again.": "O dispositivo de áudio mudou durante a gravação — a gravação foi cancelada, tente novamente.",
        "Accessibility permission is off, so the key can't be heard. Turn it on in System Settings → Privacy & Security → Accessibility — Dictate picks it up automatically, no restart needed.": "A permissão de Acessibilidade está desativada, então a tecla não é detectada. Ative em Ajustes do Sistema → Privacidade e Segurança → Acessibilidade — o Dictate detecta sozinho, sem precisar reiniciar.",
        "Microphone unavailable (no input audio format)": "Microfone indisponível (sem formato de áudio de entrada)",
        // Key names
        "Right Option (⌥)": "Option direita (⌥)",
        "Left Option (⌥)": "Option esquerda (⌥)",
        "Right Command (⌘)": "Command direita (⌘)",
        "Left Command (⌘)": "Command esquerda (⌘)",
        "Right Shift (⇧)": "Shift direita (⇧)",
        "Left Shift (⇧)": "Shift esquerda (⇧)",
        "Right Control (⌃)": "Control direita (⌃)",
        "Left Control (⌃)": "Control esquerda (⌃)",
        "Space": "Espaço",
        "Follow system": "Igual ao sistema",
        "Translating…": "Traduzindo…",
        "Tip: hold %@ instead — your speech comes out in English.": "Dica: segure %@ em vez da tecla normal — sua fala sai em inglês.",
        "Hold to talk in your language, release to insert it in English.": "Segure e fale no seu idioma; solte e o texto é inserido em inglês.",
        "Hold %@ and say it again — this time it's typed in English.": "Segure %@ e diga de novo — desta vez sai em inglês.",
        "Translate to": "Traduzir para",
        "Translation data isn't downloaded — open Settings to get it": "Os dados de tradução não foram baixados — baixe-os nos ajustes",
        "Translation data": "Dados de tradução",
        "The translate key transcribes your speech, then macOS translates it on this Mac. Picking a language may download its translation data once.": "A tecla de tradução transcreve sua fala e depois o macOS a traduz neste Mac. Ao escolher um idioma, o macOS pode baixar seus dados de tradução uma vez.",
        "Recognition runs on your Mac's Neural Engine — Whisper large-v3-turbo: 112 languages, great with accents, fast enough for live text. Translation runs on this Mac too. Your voice never leaves this computer.": "O reconhecimento roda no Neural Engine do seu Mac — Whisper large-v3-turbo: 112 idiomas, lida bem com sotaques e é rápido o bastante para o texto ao vivo. A tradução também acontece neste Mac. Sua voz nunca sai deste computador.",
        "Hold %@ and say it again — this time it comes out in %@.": "Segure %@ e diga de novo — desta vez sai em %@.",
        "Hold to talk in your language, release to insert it in %@.": "Segure e fale no seu idioma; solte e o texto é inserido em %@.",
        "Not downloaded": "Não baixados",
        "Translation languages": "Idiomas de tradução",
        "Downloaded": "Baixado",
        "Manage in System Settings…": "Gerenciar nos Ajustes do Sistema…",
        "Already ON in System Settings but not green here? Turn the Dictate switch off and back on — after an app update macOS sometimes keeps a stale entry.": "Já está ativado nos Ajustes do Sistema mas aqui não fica verde? Desligue e ligue de novo o interruptor do Dictate — após uma atualização, o macOS às vezes mantém um registro obsoleto.",
    ]

    static let fr: [String: String] = [
        "Settings": "Réglages",
        "Keyboard shortcuts": "Raccourcis clavier",
        "Storage & models": "Stockage et modèles",
        "Asking is the one thing that leaves this Mac: your question, the search hits, and the transcripts the agent opens to answer go to %@ on your key. Nothing is sent until you ask.": "Demander est la seule chose qui quitte ce Mac : votre question, les résultats de recherche et les transcriptions que l'agent ouvre pour répondre vont chez %@ avec votre clé. Rien n'est envoyé tant que vous ne demandez pas.",
        "The Keychain refused to save the key — it stays in the field. Try again after unlocking the keychain.": "Le trousseau a refusé d'enregistrer la clé — elle reste dans le champ. Déverrouillez le trousseau et réessayez.",
        "Couldn't reach the update server. Try again once you're online.": "Impossible de joindre le serveur de mise à jour. Réessayez une fois en ligne.",
        "Update %@ is on its way — downloading now, it installs itself soon.": "La mise à jour %@ arrive — téléchargement en cours, elle s'installera d'elle-même bientôt.",
        "You're up to date — Dictate %@ is the newest version.": "Vous êtes à jour — Dictate %@ est la version la plus récente.",
        "Recorded meetings appear here.": "Les réunions enregistrées apparaissent ici.",
        "This is your microphone only — the other side of the call was not recorded and cannot be recovered.": "Ceci n'est que votre micro — l'autre partie de l'appel n'a pas été enregistrée et ne peut pas être récupérée.",
        "Turning both on covers the calls that come next.": "En activant les deux, les prochains appels seront couverts.",
        "%@ refused the request for billing reasons. Add credit in your provider account, or disconnect the agent in Settings.": "%@ a refusé la requête pour des raisons de facturation. Ajoutez du crédit chez votre fournisseur ou déconnectez l'agent dans Réglages.",
        "Agent": "Agent",
        "Ask your agent": "Demander à l'agent",
        "Ask your agent anything…": "Demandez n'importe quoi à votre agent…",
        "Has read %d of %d meetings": "A lu %d réunions sur %d",
        "Has read 1 meeting": "A lu 1 réunion",
        "Has read all %d meetings": "A lu les %d réunions",
        "Meetings & Agent…": "Réunions et agent…",
        "Not now keeps the agent off and hidden. Search and transcripts are unaffected.": "Pas maintenant laisse l'agent désactivé et masqué. La recherche et les transcriptions ne sont pas affectées.",
        "Nothing to read yet": "Rien à lire pour l'instant",
        "Off — has read nothing yet": "Désactivé — n'a encore rien lu",
        "Questions are never limited to one meeting. Your agent searches everything you have recorded and the answer names the meeting and the person.": "Les questions ne se limitent jamais à une réunion. Votre agent cherche dans tout ce que vous avez enregistré et la réponse nomme la réunion et la personne.",
        "Reading %d of %d meetings…": "Lecture de %d réunions sur %d…",
        "The agent uses": "L'agent utilise",
        "This is what writes the summary and the outline, and what gives your agent something to answer from. Off, you get the raw transcript — no summary, no outline, and no agent. Nothing is sent anywhere either way.": "C'est ce qui écrit le résumé et le plan, et ce qui donne à votre agent de quoi répondre. Désactivé, il reste la transcription brute — ni résumé, ni plan, ni agent. Dans tous les cas, rien n'est envoyé nulle part.",
        "Your agent answers questions across everything you have recorded — “what did we decide about the freeze date” — and cites the meeting and moment it came from. It needs the model that reads your meetings, which is currently off. Nothing leaves this Mac either way.": "Votre agent répond aux questions sur tout ce que vous avez enregistré — « qu'avons-nous décidé pour la date de gel » — et cite la réunion et le moment d'où vient la réponse. Il lui faut le modèle qui lit vos réunions, actuellement désactivé. Dans tous les cas, rien ne quitte ce Mac.",
        "Your agent has nothing to read yet": "Votre agent n'a encore rien à lire",
        "Your agent has read 1 meeting": "Votre agent a lu 1 réunion",
        "Your agent has read all %d meetings": "Votre agent a lu les %d réunions",
        "Your agent is off": "Votre agent est désactivé",
        "Your agent is reading — %d of %d meetings so far": "Votre agent lit — %d réunions sur %d pour l'instant",
        "answers with %@": "répond avec %@",
        "Nothing here can hear a call until it is granted in System Settings › Privacy & Security › Microphone.": "Rien ici ne peut entendre un appel tant que l'accès n'est pas accordé dans Réglages Système › Confidentialité et sécurité › Micro.",
        "There is no summary or outline — reading your meetings is off.": "Il n'y a ni résumé ni plan — la lecture de vos réunions est désactivée.",
        "This is your microphone only — the other side of the call is missing, the text is one unbroken block, and there is no summary or outline.": "Ceci n'est que votre micro — l'autre partie de l'appel manque, le texte est un seul bloc, et il n'y a ni résumé ni plan.",
        "Turn both on": "Activer les deux",
        "Turn it on": "L'activer",
        "Turning it on also writes them for the recordings that come next. Writing one now leaves the switch off.": "En l'activant, ils seront aussi écrits pour les prochains enregistrements. En écrire un maintenant laisse l'interrupteur éteint.",
        "Waiting on microphone access.": "En attente de l'accès au micro.",
        "Waits for “%@” above — there is no call audio to separate yet.": "Attend « %@ » ci-dessus — il n'y a pas encore d'audio d'appel à séparer.",
        "Write one, this once": "En écrire un, pour cette fois",
        "Writing one now reads only this transcript and leaves the switches off. The other side of this call was not recorded and cannot be recovered.": "En écrire un maintenant ne lit que cette transcription et laisse les interrupteurs éteints. L'autre partie de cet appel n'a pas été enregistrée et ne peut pas être récupérée.",
        "Writing…": "Écriture…",
        "macOS denied microphone access": "macOS a refusé l'accès au micro",
        "%@ call — not being recorded": "Appel %@ — non enregistré",
        "Asked once. After this, the panel is the short version above.": "Demandé une seule fois. Ensuite, le panneau est la version courte ci-dessus.",
        "Call recording is off, so this one is passing untranscribed. Turning it on gives you a searchable transcript and a summary afterwards, kept on this Mac.": "L'enregistrement des appels est désactivé : celui-ci passe sans transcription. En l'activant, vous obtenez ensuite une transcription consultable et un résumé, conservés sur ce Mac.",
        "Call — not being recorded": "Appel — non enregistré",
        "Calls are not noticed automatically. You can start each one here, or let Dictate offer when a call begins.": "Les appels ne sont pas détectés automatiquement. Vous pouvez lancer chacun ici, ou laisser Dictate le proposer quand un appel commence.",
        "Connect a provider…": "Connecter un fournisseur…",
        "Dictation still works. Each switch below says what it adds; you can turn on one and leave the rest alone.": "La dictée fonctionne toujours. Chaque interrupteur ci-dessous dit ce qu'il ajoute ; vous pouvez en activer un et laisser les autres.",
        "Dictation works already — hold the dictation key and speak anywhere. Everything below is about meetings, and none of it is required. Turn on what you want; the rest stays off.": "La dictée fonctionne déjà — maintenez la touche de dictée et parlez n'importe où. Tout ce qui suit concerne les réunions, et rien n'est obligatoire. Activez ce que vous voulez ; le reste reste désactivé.",
        "Don't offer this again": "Ne plus proposer",
        "Everything here is off, so calls pass unnoticed": "Tout est désactivé ici : les appels passent inaperçus",
        "Let the model read your meetings": "Laisser le modèle lire vos réunions",
        "Not watching for calls": "Appels non surveillés",
        "Notice when a call starts": "Détecter le début d'un appel",
        "Off, a recording holds your microphone only — your half of the conversation, in one unbroken block. On, both sides are transcribed as named turns.": "Désactivé, un enregistrement ne contient que votre micro — votre moitié de la conversation, en un seul bloc. Activé, les deux côtés sont transcrits en répliques nommées.",
        "Off, you get only your own microphone — your half of the conversation. On, the other side is transcribed as well.": "Désactivé, vous n'avez que votre micro — votre moitié de la conversation. Activé, l'autre côté est aussi transcrit.",
        "On": "Activé",
        "Or leave this and set them up later in Settings.": "Ou laissez cela et configurez-les plus tard dans Réglages.",
        "Read meeting names from Calendar": "Lire les noms des réunions dans Calendrier",
        "Record the call audio too": "Enregistrer aussi l'audio de l'appel",
        "Record the call audio, and separate the voices": "Enregistrer l'audio de l'appel et séparer les voix",
        "Recordings arrive already titled instead of as “Zoom call, 14:02”. Only titles overlapping a recording are read.": "Les enregistrements arrivent déjà titrés, au lieu de « Appel Zoom, 14:02 ». Seuls les titres qui chevauchent un enregistrement sont lus.",
        "Separate the voices": "Séparer les voix",
        "Set up calls…": "Configurer les appels…",
        "The agent searches and reads your transcripts on this Mac; the written answer comes from a provider you connect with your own key.": "L'agent cherche et lit vos transcriptions sur ce Mac ; la réponse écrite vient d'un fournisseur que vous connectez avec votre propre clé.",
        "Three things are off. Here is what each one adds.": "Trois choses sont désactivées. Voici ce que chacune apporte.",
        "Turn all on": "Tout activer",
        "Turn all three on": "Activer les trois",
        "Turn on": "Activer",
        "Turn on reading": "Activer la lecture",
        "Turns one block of text into named turns, so you can see who committed to what. Names are yours to set and can be changed after the fact.": "Transforme un bloc de texte en répliques nommées, pour voir qui s'est engagé à quoi. Les noms sont à vous et peuvent être changés après coup.",
        "Watching for calls": "Surveillance des appels",
        "What it does": "Ce que ça fait",
        "With this on, a small panel appears when a call starts and you decide there — no need to remember to start anything.": "Activé, un petit panneau apparaît quand un appel commence et vous décidez là — pas besoin de penser à lancer quoi que ce soit.",
        "listening": "à l'écoute",
        "Back to the top": "Revenir en haut",
        "Show everything tagged #%@": "Afficher tout ce qui porte #%@",
        "Remove #%@ from this meeting": "Retirer #%@ de cette réunion",
        "Tag": "Tag",
        "Create #%@": "Créer #%@",
        "Show Live Transcript": "Afficher la transcription en cours",
        "Hide": "Masquer",
        "Stop recording": "Arrêter l’enregistrement",
        "Show transcript": "Afficher la transcription",
        "Recording": "Enregistrement",
        "Recording · %@": "Enregistrement · %@",
        "It holds about 4.7 GB of memory while it writes, which this Mac will feel.": "Pendant qu’il écrit, il occupe environ 4,7 Go de mémoire, ce que ce Mac ressentira.",
        "Your meetings are named by their date. A one-time download, kept on this Mac, writes titles, summaries and a table of contents.": "Vos réunions portent leur date comme nom. Un téléchargement unique, qui reste sur ce Mac, leur donne des titres, des résumés et un sommaire.",
        "The built-in model had nothing to say about this meeting. A one-time download, kept on this Mac, is not restricted that way.": "Le modèle intégré n’a rien eu à dire sur cette réunion. Un téléchargement unique, qui reste sur ce Mac, n’a pas cette restriction.",
        "On this Mac it runs on the CPU: about three minutes of background work for a 50-minute meeting.": "Sur ce Mac, tout passe par le processeur : environ trois minutes de travail en arrière-plan pour une réunion de 50 minutes.",
        "Not now": "Pas maintenant",
        "Meeting titles & summaries": "Titres et résumés de réunions",
        "One-time %@ download, then everything runs on this Mac.": "Un seul téléchargement de %@, ensuite tout fonctionne sur ce Mac.",
        "Names, a one-line summary and a table of contents, written on this Mac.": "Noms, résumé d'une ligne et sommaire, générés sur ce Mac.",
        "Download %@": "Télécharger %@",
        "Checking…": "Vérification…",
        "Retry": "Réessayer",
        "You": "Vous",
        "Them": "Eux",
        "Meeting transcript": "Transcription de la réunion",
        "Cancel": "Annuler",
        "Couldn't start the meeting transcript: %@": "Impossible de démarrer la transcription de la réunion : %@",
