        "Meetings": "Meetings",
        "Add your Anthropic API key in Settings to ask questions": "Anthropic-API-Schlüssel in den Einstellungen hinzufügen, um Fragen zu stellen",
        "Add your OpenAI API key in Settings to ask questions": "OpenAI-API-Schlüssel in den Einstellungen hinzufügen, um Fragen zu stellen",
