        "Save": "Sichern",
        "%d min": "%d Min",
        "%d s": "%d s",
        "System audio recording is not allowed. Enable Dictate in System Settings → Privacy & Security → Screen & System Audio Recording, then try again.": "Die Aufnahme des Systemaudios ist nicht erlaubt. Aktivieren Sie Dictate in den Systemeinstellungen → Datenschutz & Sicherheit → Bildschirm- und Systemaudio-Aufnahme und versuchen Sie es erneut.",
        "Stop": "Stopp",
        "Automatic (any language)": "Automatisch (jede Sprache)",
        "detect while you speak": "wird beim Sprechen erkannt",
        "Search language…": "Sprache suchen…",
        "Suggested": "Vorschläge",
        "No language matches your search.": "Keine Sprache gefunden.",
        "Translate key": "Übersetzungstaste",
        "%@ is using the microphone right now — close it and try again": "%@ verwendet gerade das Mikrofon — schließe es und versuche es erneut",
        "That was very quiet — move closer to the microphone": "Das war sehr leise — geh näher ans Mikrofon",
        "That was too loud — move back a little from the microphone": "Das war zu laut — geh etwas weiter vom Mikrofon weg",
        "Sorry, I didn't catch that — could you say it again?": "Entschuldige, ich habe dich nicht verstanden — kannst du das wiederholen?",
        "Not inserted — text copied, press ⌘V to paste": "Nicht eingefügt — Text kopiert, ⌘V zum Einfügen",
        "Another app is using the microphone right now — close it and try again": "Eine andere App nutzt gerade das Mikrofon — schließe sie und versuch es erneut",
        "Shortcuts": "Tastenkürzel",
        "General": "Allgemein",
        "Status": "Status",
        "Type a key…": "Taste drücken …",
        "Hold to talk, release to insert what you said.": "Halten zum Sprechen, loslassen zum Einfügen des Gesagten.",
        "Version": "Version",
        "Downloaded %d of %d MB": "%d von %d MB heruntergeladen",
        "Preparing the model for the Neural Engine… A few minutes, one time.": "Das Modell wird für die Neural Engine vorbereitet… Ein paar Minuten, einmalig.",
        "Warming up the model…": "Modell wird aufgewärmt…",
        "Dictate is running from the downloaded image — drag it into Applications, eject the image, and launch it from there. Permissions granted to this temporary copy won't stick.": "Dictate läuft aus dem heruntergeladenen Image — ziehen Sie es in „Programme“, werfen Sie das Image aus und starten Sie es von dort. Berechtigungen für diese temporäre Kopie bleiben nicht erhalten.",
        "Still stuck? Reset the permission — this clears the broken macOS record, then grant the fresh request.": "Immer noch blockiert? Setzen Sie die Berechtigung zurück — das löscht den defekten macOS-Eintrag; erteilen Sie sie dann in der neuen Abfrage.",
        "Words: %d · %.1f s": "Wörter: %d · %.1f s",
        "Words: %d": "Wörter: %d",
        "Cancelled": "Abgebrochen",
        "Changed your mind? Esc cancels the recording.": "Umentschieden? Esc bricht die Aufnahme ab.",
        "Network access: a one-time model download — nothing else. Don't take our word for it: turn off Wi-Fi and dictate.": "Netzwerkzugriff: ein einmaliger Modell-Download — sonst nichts. Glauben Sie uns nicht einfach: Schalten Sie Wi-Fi aus und diktieren Sie.",
        "About Dictate": "Über Dictate",
        // Onboarding — general
        "Welcome to Dictate": "Willkommen bei Dictate",
        "Back": "Zurück",
        "Next": "Weiter",
        "Step %d of %d": "Schritt %d von %d",
        // Welcome
        // Hotkey
        "Dictation key": "Diktiertaste",
        "This key types characters — they'll end up in your text while you hold it. A modifier (Option, Cmd, Shift, Ctrl) or an F-key is safer.": "Diese Taste erzeugt Zeichen — solange Sie sie halten, landen sie in Ihrem Text. Sicherer ist eine Modifikatortaste (Option, Cmd, Shift, Ctrl) oder eine F-Taste.",
        // Permissions
        "Microphone": "Mikrofon",
        "Accessibility": "Bedienungshilfen (Accessibility)",
        // Settings
        "Dictate Settings": "Dictate-Einstellungen",
        "This key types characters — they'll go into the text during dictation. A modifier or F-key is better.": "Die Taste erzeugt Zeichen — beim Diktieren landen sie im Text. Besser eine Modifikatortaste oder F-Taste.",
        "Launch at login": "Bei der Anmeldung starten",
        "Show in Dock": "Im Dock anzeigen",
        "The agent searches and reads your transcripts on this Mac, and every answer names the meetings it drew from.": "Der Agent durchsucht und liest Ihre Transkripte auf diesem Mac, und jede Antwort nennt die Meetings, auf die sie sich stützt.",
        "Undo remove": "Entfernen widerrufen",
        "Call started": "Ein Anruf hat begonnen",
        "Recording stopped by itself — the call ended.": "Die Aufnahme hat sich selbst beendet — der Anruf ist zu Ende.",
        "Recording stopped by itself — ten minutes of silence.": "Die Aufnahme hat sich selbst beendet — zehn Minuten Stille.",
        "%@ call started": "%@-Anruf gestartet",
        "Not this one": "Diesen nicht",
        "Record": "Aufnehmen",
        "Record this call": "Diesen Anruf aufnehmen",
        "Dictation that works offline — recognition runs entirely on this Mac.": "Diktat, das offline funktioniert — die Erkennung läuft vollständig auf diesem Mac.",
        "Translation that works offline — speak your language, another comes out.": "Übersetzung, die offline funktioniert — sprechen Sie Ihre Sprache, eine andere kommt heraus.",
        "Meetings, recorded and structured: speakers, summary, outline, search.": "Meetings, aufgezeichnet und strukturiert: Sprecher, Zusammenfassung, Gliederung, Suche.",
        "An optional agent that knows your meetings — answers quote the moment they came from.": "Ein optionaler Agent, der Ihre Meetings kennt — Antworten zitieren den Moment, aus dem sie stammen.",
        "%d MB of %d MB": "%d MB von %d MB",
        "Already clicked and nothing changed?": "Geklickt und nichts passiert?",
        "Applications": "Programme",
        "Downloading the speech model": "Sprachmodell wird geladen",
        "Grant…": "Erteilen…",
        "Nothing here leaves this window. Two small things to try, then you are done.": "Nichts verlässt dieses Fenster. Zwei kleine Versuche, dann sind Sie fertig.",
        "Resume Download": "Download fortsetzen",
        "Show me where to look": "Zeig mir, wo ich nachsehen muss",
        "Start Dictate when I log in — it appears in the Dock and the menu bar, and the Dock icon can be hidden later in Settings": "Dictate beim Anmelden starten — es erscheint im Dock und in der Menüleiste; das Dock-Symbol lässt sich später in den Einstellungen ausblenden",
        "Start Using Dictate": "Dictate jetzt verwenden",
        "Stopped · %d MB of %d MB kept on disk": "Gestoppt · %d MB von %d MB auf der Festplatte behalten",
        "The connection was interrupted. Resuming continues from where it stopped — you will not download the whole %d MB again.": "Die Verbindung wurde unterbrochen. Beim Fortsetzen geht es an derselben Stelle weiter — Sie laden nicht die ganzen %d MB erneut.",
        "The download stopped at %d MB": "Der Download stoppte bei %d MB",
        "The model is being compiled for your chip so recognition is fast later. This takes a minute on first launch and never happens again.": "Das Modell wird für Ihren Chip kompiliert, damit die Erkennung später schnell ist. Das dauert beim ersten Start eine Minute und passiert nie wieder.",
        "This happens once. The model stays on your Mac and is the reason dictation works without an internet connection afterwards.": "Das passiert einmal. Das Modell bleibt auf Ihrem Mac — deshalb funktioniert das Diktieren danach ohne Internetverbindung.",
        "To hear you. Audio is processed on this Mac and discarded.": "Um Sie zu hören. Audio wird auf diesem Mac verarbeitet und verworfen.",
        "To type the recognized text into the app you are using. It is the only way an app can insert text elsewhere.": "Um den erkannten Text in die App zu tippen, die Sie gerade verwenden. Nur so kann eine App Text anderswo einfügen.",
        "Try it here first": "Probieren Sie es zuerst hier",
        "Two permissions from macOS": "Zwei Berechtigungen von macOS",
        "macOS asks for these, not us. Dictate cannot work without both.": "macOS fragt danach, nicht wir. Ohne beide kann Dictate nicht arbeiten.",
        "Show or hide the conversations": "Unterhaltungen ein- oder ausblenden",
        "Show or hide the sidebar": "Seitenleiste ein- oder ausblenden",
        "Show or hide the meeting list": "Meetingliste ein- oder ausblenden",
        "Preparing the model for this Mac": "Modell wird für diesen Mac vorbereitet",
        "Not ready yet — this takes a few seconds after launch. Keep holding %@ and it will start.": "Noch nicht bereit — nach dem Start dauert das ein paar Sekunden. Halten Sie %@ gedrückt, dann geht es los.",
        "Transcript text": "Transkript-Text",
        "Smaller text": "Kleinerer Text",
        "Standard text": "Standardtext",
        "Larger text": "Größerer Text",
        "112 languages · from your system settings": "112 Sprachen · aus den Systemeinstellungen",
        "Add tag": "Tag hinzufügen",
        "Appearance": "Erscheinungsbild",
        "Asked once. After this, recording starts from the menu bar without a prompt. Esc means don't record.": "Einmal gefragt. Danach startet die Aufnahme aus der Menüleiste ohne Rückfrage. Esc heißt: nicht aufnehmen.",
        "Check for updates": "Nach Updates suchen",
        "Choose your keys and languages": "Tasten und Sprachen wählen",
        "Click, then press a key": "Klicken, dann eine Taste drücken",
        "Dark": "Dunkel",
        "Dictate stays dark even when macOS switches. Every surface follows: the window, the dictation overlay, the recording pill and the menu.": "Dictate bleibt dunkel, auch wenn macOS wechselt. Alle Flächen folgen: das Fenster, das Diktier-Overlay, die Aufnahme-Pille und das Menü.",
        "Dictate stays light even when macOS switches. Every surface follows: the window, the dictation overlay, the recording pill and the menu.": "Dictate bleibt hell, auch wenn macOS wechselt. Alle Flächen folgen: das Fenster, das Diktier-Overlay, die Aufnahme-Pille und das Menü.",
        "Dictate will record your microphone and the audio from the call, and keep the transcript on this Mac. Recording other people may require their consent where you are.": "Dictate nimmt Ihr Mikrofon und den Ton des Anrufs auf und behält das Transkript auf diesem Mac. Andere aufzunehmen kann dort, wo Sie sind, deren Einwilligung erfordern.",
        "Don't Record": "Nicht aufnehmen",
        "Follows the macOS setting, switching with it at sunset. Choose Light or Dark to hold Dictate to one appearance regardless of the system.": "Folgt der macOS-Einstellung und wechselt mit ihr bei Sonnenuntergang. Wählen Sie Hell oder Dunkel, um Dictate unabhängig vom System festzulegen.",
        "Hold the key while you speak. Anything can be changed later in Settings.": "Halten Sie die Taste, während Sie sprechen. Alles lässt sich später in den Einstellungen ändern.",
        "I speak": "Ich spreche",
        "Light": "Hell",
        "Looking through %d meetings…": "Durchsehe %d Meetings…",
        "Match system": "Wie das System",
        "Modifier keys work best: they never insert a character when you hold them. Esc always cancels a dictation in progress.": "Modifikatortasten funktionieren am besten: Gehalten fügen sie nie ein Zeichen ein. Esc bricht ein laufendes Diktat immer ab.",
        "Reading “%@”…": "Lese „%@“…",
        "Record this call?": "Diesen Anruf aufnehmen?",
        "Searching your meetings…": "Durchsuche Ihre Meetings…",
        "Start Recording": "Aufnahme starten",
        "Tags": "Tags",
        "Voices": "Stimmen",
        "Summary": "Zusammenfassung",
        "Outline": "Gliederung",
        "Hide outline": "Gliederung ausblenden",
        "Show outline": "Gliederung einblenden",
        "two levels": "zwei Ebenen",
        "three levels": "drei Ebenen",
        "%d moments": "%d Momente",
        "Kept on this Mac. Deleting is immediate; beyond 50 conversations the oldest age out.": "Bleibt auf diesem Mac. Löschen wirkt sofort; ab 50 Unterhaltungen fallen die ältesten heraus.",
        "Ask across all meetings…": "In allen Meetings fragen…",
        "Recently Added": "Zuletzt hinzugefügt",
        "%d meetings · %d h of audio": "%d Meetings · %d Std. Audio",
        "%d meetings · %d min of audio": "%d Meetings · %d Min. Audio",
        "Show more": "Mehr anzeigen",
        "Try one of these": "Probieren Sie eine davon",
        "Accessibility access is turned off": "Der Bedienungshilfen-Zugriff ist ausgeschaltet",
        "Dictation can hear you but cannot type. Re-enable it to continue.": "Das Diktat hört Sie, kann aber nicht tippen. Aktivieren Sie den Zugriff erneut.",
        "Recent dictations": "Letzte Diktate",
        "Secure input is active — the hotkey cannot work": "Sichere Eingabe ist aktiv — die Taste kann nicht funktionieren",
        "Something has a password field focused. macOS does not say which app. Click into an ordinary text field and dictation works again.": "Irgendwo ist ein Passwortfeld fokussiert. macOS sagt nicht, in welcher App. Klicken Sie in ein gewöhnliches Textfeld, und das Diktat funktioniert wieder.",
        "Start Recording Meeting": "Meeting aufnehmen",
        "Stop Recording Meeting": "Meeting-Aufnahme stoppen",
        "click to copy": "Klick = kopieren",
        "dictate in %@": "diktieren auf %@",
        "dictate in any language": "diktieren in jeder Sprache",
        "translate %@ → %@": "übersetzen %@ → %@",
        "translate into %@": "übersetzen nach %@",
        "%d waiting": "%d wartet",
        "%d words typed": "%d Wörter getippt",
        "Add a Key…": "Schlüssel hinzufügen…",
        "Both will be inserted in the order you spoke them": "Beide werden in der Reihenfolge eingefügt, in der Sie sie gesprochen haben",
        "Check Audio Setup": "Audio-Setup prüfen",
        "Clear All Filters": "Alle Filter löschen",
        "F-keys can also trigger a system control (brightness, media) — macOS will do both. To use one as a plain key, turn on “Use F1, F2, etc. as standard function keys” in Keyboard settings.": "F-Tasten lösen oft auch eine Systemfunktion aus (Helligkeit, Medien) — macOS macht beides. Um sie als normale Taste zu nutzen, aktivieren Sie „Use F1, F2, etc. as standard function keys“ in den Tastatureinstellungen.",
        "How this works": "So funktioniert es",
        "Input device changed": "Eingabegerät geändert",
        "Insert text by": "Text einfügen per",
        "It was revoked or replaced since you connected. It has been removed from the Keychain — nothing was retried with it.": "Er wurde seit der Verbindung widerrufen oder ersetzt. Er wurde aus dem Schlüsselbund entfernt — nichts wurde damit erneut gesendet.",
        "Join a call in the browser, then start recording. Dictate captures your microphone and the call audio, transcribes both on this Mac, and keeps the transcript here. Nothing is uploaded.": "Treten Sie einem Anruf im Browser bei und starten Sie die Aufnahme. Dictate erfasst Ihr Mikrofon und den Anrufton, transkribiert beides auf diesem Mac und behält das Transkript hier. Nichts wird hochgeladen.",
        "No meeting has all of these tags": "Kein Meeting trägt alle diese Tags",
        "No meeting has this tag": "Kein Meeting trägt diesen Tag",
        "Nothing was said, or nothing was heard": "Nichts wurde gesagt — oder nichts wurde gehört",
        "Only the unconfirmed tail is shown here — the rest is already in the document": "Hier steht nur der unbestätigte Rest — alles andere ist schon im Dokument",
        "Open Console": "Konsole öffnen",
        "Open Settings": "Einstellungen öffnen",
        "Pasting is instant but replaces your clipboard for a moment. Typing works in apps that block paste, such as some terminals and remote desktops.": "Einfügen ist sofort, ersetzt aber kurz die Zwischenablage. Tippen funktioniert in Apps, die Einfügen blockieren, etwa manchen Terminals und Remote-Desktops.",
        "Pasting it at once": "Auf einmal einfügen",
        "Recording ended here — this Mac went to sleep.": "Die Aufnahme endete hier — dieser Mac ging in den Ruhezustand.",
        "Remove “%@”": "„%@“ entfernen",
        "Return sends · Shift-Return adds a line · Esc clears": "Zeilenschalter sendet · Umschalt-Zeilenschalter neue Zeile · Esc leert",
        "Show Floating Timer": "Schwebenden Timer zeigen",
        "Start Recording a Meeting": "Meeting aufnehmen",
        "Still recognizing the previous dictation": "Das vorige Diktat wird noch erkannt",
        "Still recognizing the previous dictation · %d words": "Das vorige Diktat wird noch erkannt · %d Wörter",
        "Switched to %@": "Gewechselt zu %@",
        "Tag filters combine with “and” — a meeting must carry every selected tag to appear.": "Tag-Filter verbinden sich mit „und“ — ein Meeting muss jeden gewählten Tag tragen.",
        "The answer stopped. Your question is kept above — retry when the connection returns. Search and transcripts still work.": "Die Antwort brach ab. Ihre Frage bleibt oben — versuchen Sie es erneut, sobald die Verbindung zurück ist. Suche und Transkripte funktionieren weiter.",
        "The recording ran, but no speech was recognized on either side. Usually this means the call audio was never captured — a browser tab without audio permission, or the wrong output device.": "Die Aufnahme lief, aber auf keiner Seite wurde Sprache erkannt. Meist wurde der Anrufton nie erfasst — ein Browser-Tab ohne Audioberechtigung oder das falsche Ausgabegerät.",
        "The saved key no longer works": "Der gesicherte Schlüssel funktioniert nicht mehr",
        "The switch stays off until it is granted in System Settings › Privacy & Security › Calendars. Only event titles that overlap a recording are ever read.": "Der Schalter bleibt aus, bis der Zugriff in System Settings › Privacy & Security › Calendars erteilt ist. Gelesen werden nur Termine, die eine Aufnahme überlappen.",
        "This Mac is offline": "Dieser Mac ist offline",
        "Too many questions at once": "Zu viele Fragen auf einmal",
        "Typing as you speak": "Tippt, während Sie sprechen",
        "Typing into %@ as you speak": "Tippt in %@, während Sie sprechen",
        "Typing it out character by character": "Zeichen für Zeichen tippen",
        "Your provider account is out of credit": "Das Anbieterkonto hat kein Guthaben mehr",
        "Your provider is rate limiting. Wait a few seconds and retry — nothing was lost.": "Ihr Anbieter drosselt die Anfragen. Warten Sie ein paar Sekunden — nichts ging verloren.",
        "macOS denied calendar access": "macOS hat den Kalenderzugriff verweigert",
        "API key": "API-Schlüssel",
        "All Meetings": "Alle Meetings",
        "Assistant": "Assistent",
        "Checking the key with %@. No transcript is sent — only a test request.": "Schlüssel wird bei %@ geprüft. Es wird kein Transkript gesendet — nur eine Testanfrage.",
        "Closing the window does not stop the recording. Stop it here, or from the menu bar at any time.": "Das Schließen des Fensters stoppt die Aufnahme nicht. Stoppen Sie sie hier oder jederzeit über die Menüleiste.",
        "Connect an assistant to answer questions": "Assistenten verbinden, um Fragen zu beantworten",
        "Dictate can record a browser call and keep the transcript on this Mac. Start one from the menu bar when your next call begins — you will be asked for consent once.": "Dictate kann einen Browser-Anruf aufnehmen und das Transkript auf diesem Mac behalten. Starten Sie die Aufnahme beim nächsten Anruf über die Menüleiste — die Zustimmung wird einmal erfragt.",
        "Done": "Fertig",
        "Every change takes effect immediately.": "Jede Änderung wirkt sofort.",
        "Get one at %@.": "Erhältlich auf %@.",
        "Hold a key, speak, let go. What you said is typed where your cursor is, in any app on this Mac.": "Taste halten, sprechen, loslassen. Das Gesagte wird dort getippt, wo der Cursor steht — in jeder App auf diesem Mac.",
        "Keys": "Tasten",
        "Languages": "Sprachen",
        "Library": "Bibliothek",
        "Paste a key from your own account.": "Fügen Sie einen Schlüssel Ihres eigenen Kontos ein.",
