        "System audio recording is not allowed. Enable Dictate in System Settings → Privacy & Security → Screen & System Audio Recording, then try again.": "不允许录制系统音频。请在系统设置 → 隐私与安全性 → 屏幕与系统音频录制中启用 Dictate，然后重试。",
        "Stop": "停止",
