        "Translate key": "翻译键",
        "%@ is using the microphone right now — close it and try again": "%@ 正在使用麦克风——请关闭它后重试",
        "That was very quiet — move closer to the microphone": "声音太小了——请靠近麦克风",
        "That was too loud — move back a little from the microphone": "声音太大了——请离麦克风远一点",
        "Sorry, I didn't catch that — could you say it again?": "抱歉，我没有听清 — 能再说一遍吗？",
        "Not inserted — text copied, press ⌘V to paste": "未插入 — 文本已复制，按 ⌘V 粘贴",
        "Another app is using the microphone right now — close it and try again": "另一个应用正在使用麦克风 — 请关闭后重试",
        "Shortcuts": "快捷键",
        "General": "通用",
        "Status": "状态",
        "Type a key…": "按下一个键…",
        "Hold to talk, release to insert what you said.": "按住说话，松开即插入你说的内容。",
        "Version": "版本",
        "Downloaded %d of %d MB": "已下载 %d / %d MB",
        "Preparing the model for the Neural Engine… A few minutes, one time.": "正在为 Neural Engine 准备模型…几分钟，仅此一次。",
        "Warming up the model…": "正在预热模型…",
        "Dictate is running from the downloaded image — drag it into Applications, eject the image, and launch it from there. Permissions granted to this temporary copy won't stick.": "Dictate 正从下载的镜像中运行——请将它拖入“应用程序”，推出镜像，然后从那里启动。授予这个临时副本的权限不会保留。",
        "Still stuck? Reset the permission — this clears the broken macOS record, then grant the fresh request.": "还是不行？重置权限——这会清除 macOS 中损坏的记录，然后在新的请求中重新授权。",
        "Words: %d · %.1f s": "词数：%d · %.1f 秒",
        "Words: %d": "词数：%d",
        "Cancelled": "已取消",
        "Changed your mind? Esc cancels the recording.": "改变主意了？按 Esc 取消录音。",
        "Network access: a one-time model download — nothing else. Don't take our word for it: turn off Wi-Fi and dictate.": "网络访问：仅用于一次性下载模型——再无其他。别只听我们说：关掉 Wi-Fi，照样听写。",
        "About Dictate": "关于 Dictate",
        // Onboarding — general
        "Welcome to Dictate": "欢迎使用 Dictate",
        "Back": "返回",
        "Next": "下一步",
        "Step %d of %d": "第 %d 步，共 %d 步",
        // Welcome
        // Hotkey
        "Dictation key": "听写按键",
        "This key types characters — they'll end up in your text while you hold it. A modifier (Option, Cmd, Shift, Ctrl) or an F-key is safer.": "这个键会输入字符——按住期间字符会混入文本。选择修饰键（Option、Cmd、Shift、Ctrl）或 F 功能键更稳妥。",
        // Permissions
        "Microphone": "麦克风",
        "Accessibility": "辅助功能 (Accessibility)",
        // Settings
        "Dictate Settings": "Dictate 设置",
        "This key types characters — they'll go into the text during dictation. A modifier or F-key is better.": "这个键会输入字符——听写时它们会混入文本。建议使用修饰键或 F 功能键。",
        "Launch at login": "登录时启动",
        "Show in Dock": "在程序坞中显示",
        "The agent searches and reads your transcripts on this Mac, and every answer names the meetings it drew from.": "智能体在这台 Mac 上搜索并阅读你的转录，每个回答都会注明依据的会议。",
        "Undo remove": "撤销移除",
        "Call started": "通话已开始",
        "Recording stopped by itself — the call ended.": "录制已自动停止 — 通话已结束。",
        "Recording stopped by itself — ten minutes of silence.": "录制已自动停止 — 十分钟无声。",
        "%@ call started": "%@ 通话已开始",
        "Not this one": "这个不录",
        "Record": "录制",
        "Record this call": "录制这个通话",
        "Dictation that works offline — recognition runs entirely on this Mac.": "离线可用的听写 — 识别完全在这台 Mac 上进行。",
        "Translation that works offline — speak your language, another comes out.": "离线可用的翻译 — 说你的语言，输出另一种。",
        "Meetings, recorded and structured: speakers, summary, outline, search.": "会议被记录并结构化：说话人、摘要、大纲、搜索。",
        "An optional agent that knows your meetings — answers quote the moment they came from.": "可选的智能体了解你的会议 — 回答会引用它出自的那一刻。",
        "%d MB of %d MB": "%d MB / %d MB",
        "Already clicked and nothing changed?": "点了却没有任何变化？",
        "Applications": "应用程序",
        "Downloading the speech model": "正在下载语音模型",
        "Grant…": "授权…",
        "Nothing here leaves this window. Two small things to try, then you are done.": "这里的一切都不会离开此窗口。试两件小事，就完成了。",
        "Resume Download": "继续下载",
        "Show me where to look": "告诉我去哪里看",
        "Start Dictate when I log in — it appears in the Dock and the menu bar, and the Dock icon can be hidden later in Settings": "登录时启动 Dictate — 它会出现在程序坞和菜单栏；程序坞图标可稍后在设置中隐藏",
        "Start Using Dictate": "开始使用 Dictate",
        "Stopped · %d MB of %d MB kept on disk": "已停止 · 磁盘上保留了 %d MB / %d MB",
        "The connection was interrupted. Resuming continues from where it stopped — you will not download the whole %d MB again.": "连接中断了。恢复后会从停止的地方继续 — 不必重新下载全部 %d MB。",
        "The download stopped at %d MB": "下载在 %d MB 处停止",
        "The model is being compiled for your chip so recognition is fast later. This takes a minute on first launch and never happens again.": "模型正在为你的芯片编译，之后识别会很快。首次启动需要一分钟，以后不会再发生。",
        "This happens once. The model stays on your Mac and is the reason dictation works without an internet connection afterwards.": "这只发生一次。模型保存在你的 Mac 上 — 这就是之后听写无需联网的原因。",
        "To hear you. Audio is processed on this Mac and discarded.": "用来听到你。音频在这台 Mac 上处理并丢弃。",
        "To type the recognized text into the app you are using. It is the only way an app can insert text elsewhere.": "用来把识别出的文字输入到你正在使用的应用中。这是应用向其他应用插入文字的唯一方式。",
        "Try it here first": "先在这里试试",
        "Two permissions from macOS": "来自 macOS 的两项权限",
        "macOS asks for these, not us. Dictate cannot work without both.": "这些是 macOS 在询问，不是我们。两项都没有，Dictate 无法工作。",
        "Show or hide the conversations": "显示或隐藏对话",
        "Show or hide the sidebar": "显示或隐藏边栏",
        "Show or hide the meeting list": "显示或隐藏会议列表",
        "Preparing the model for this Mac": "正在为这台 Mac 准备模型",
        "Not ready yet — this takes a few seconds after launch. Keep holding %@ and it will start.": "尚未就绪 — 启动后需要几秒钟。按住 %@ 不放，即将开始。",
        "Transcript text": "转录文字",
        "Smaller text": "较小文字",
        "Standard text": "标准文字",
        "Larger text": "较大文字",
        "112 languages · from your system settings": "112 种语言 · 来自系统设置",
        "Add tag": "添加标签",
        "Appearance": "外观",
        "Asked once. After this, recording starts from the menu bar without a prompt. Esc means don't record.": "只询问一次。之后录制会直接从菜单栏开始，不再提示。按 Esc 表示不录制。",
        "Check for updates": "检查更新",
        "Choose your keys and languages": "选择按键和语言",
        "Click, then press a key": "点击后按下一个键",
        "Dark": "深色",
        "Dictate stays dark even when macOS switches. Every surface follows: the window, the dictation overlay, the recording pill and the menu.": "即使 macOS 切换外观，Dictate 也保持深色。所有界面都会跟随：窗口、听写浮层、录制胶囊和菜单。",
        "Dictate stays light even when macOS switches. Every surface follows: the window, the dictation overlay, the recording pill and the menu.": "即使 macOS 切换外观，Dictate 也保持浅色。所有界面都会跟随：窗口、听写浮层、录制胶囊和菜单。",
        "Dictate will record your microphone and the audio from the call, and keep the transcript on this Mac. Recording other people may require their consent where you are.": "Dictate 将录制你的麦克风和通话音频，并把转录保存在这台 Mac 上。录制他人可能需要征得对方同意，视你所在地区而定。",
        "Don't Record": "不录制",
        "Follows the macOS setting, switching with it at sunset. Choose Light or Dark to hold Dictate to one appearance regardless of the system.": "跟随 macOS 设置，在日落时一同切换。选择浅色或深色可让 Dictate 固定外观，不受系统影响。",
        "Hold the key while you speak. Anything can be changed later in Settings.": "说话时按住该键。之后都可以在设置中更改。",
        "I speak": "我说",
        "Light": "浅色",
        "Looking through %d meetings…": "正在浏览 %d 个会议…",
        "Match system": "跟随系统",
        "Modifier keys work best: they never insert a character when you hold them. Esc always cancels a dictation in progress.": "修饰键效果最好：按住它们不会输入字符。Esc 随时取消正在进行的听写。",
        "Reading “%@”…": "正在阅读“%@”…",
        "Record this call?": "录制这个通话？",
        "Searching your meetings…": "正在搜索你的会议…",
        "Start Recording": "开始录制",
        "Tags": "标签",
        "Voices": "声音",
        "Summary": "摘要",
        "Outline": "大纲",
        "Hide outline": "隐藏大纲",
        "Show outline": "显示大纲",
        "two levels": "两级",
        "three levels": "三级",
        "%d moments": "%d 个时刻",
        "Kept on this Mac. Deleting is immediate; beyond 50 conversations the oldest age out.": "保存在这台 Mac 上。删除立即生效；超过 50 个对话后最旧的会被淘汰。",
        "Ask across all meetings…": "在所有会议中提问…",
        "Recently Added": "最近添加",
        "%d meetings · %d h of audio": "%d 个会议 · %d 小时音频",
        "%d meetings · %d min of audio": "%d 个会议 · %d 分钟音频",
        "Show more": "显示更多",
        "Try one of these": "试试这些",
        "Accessibility access is turned off": "辅助功能权限已关闭",
        "Dictation can hear you but cannot type. Re-enable it to continue.": "听写能听到你，但无法输入。重新启用后才能继续。",
        "Recent dictations": "最近的听写",
        "Secure input is active — the hotkey cannot work": "安全输入已启用 — 快捷键无法工作",
        "Something has a password field focused. macOS does not say which app. Click into an ordinary text field and dictation works again.": "某个应用的密码框处于焦点。macOS 不会说是哪个。点进普通文本框，听写就恢复了。",
        "Start Recording Meeting": "录制会议",
        "Stop Recording Meeting": "停止录制会议",
        "click to copy": "点按即复制",
        "dictate in %@": "用%@听写",
        "dictate in any language": "任意语言听写",
        "translate %@ → %@": "翻译 %@ → %@",
        "translate into %@": "翻译成%@",
        "%d waiting": "%d 个等待中",
        "%d words typed": "已输入 %d 个词",
        "Add a Key…": "添加密钥…",
        "Both will be inserted in the order you spoke them": "两段将按你说出的顺序依次插入",
        "Check Audio Setup": "检查音频设置",
        "Clear All Filters": "清除所有筛选",
        "F-keys can also trigger a system control (brightness, media) — macOS will do both. To use one as a plain key, turn on “Use F1, F2, etc. as standard function keys” in Keyboard settings.": "F 键通常也触发系统控制（亮度、媒体）— macOS 会两者都执行。要将其用作普通按键，请在键盘设置中开启「Use F1, F2, etc. as standard function keys」。",
        "How this works": "工作原理",
        "Input device changed": "输入设备已更改",
        "Insert text by": "插入文本方式",
        "It was revoked or replaced since you connected. It has been removed from the Keychain — nothing was retried with it.": "它在连接后已被撤销或更换。已从钥匙串中移除 — 未用它重试任何请求。",
        "Join a call in the browser, then start recording. Dictate captures your microphone and the call audio, transcribes both on this Mac, and keeps the transcript here. Nothing is uploaded.": "在浏览器中加入通话，然后开始录制。Dictate 会捕获你的麦克风和通话音频，在这台 Mac 上转录两者，并把转录保存在这里。不会上传任何内容。",
        "No meeting has all of these tags": "没有会议带有所有这些标签",
        "No meeting has this tag": "没有会议带有这个标签",
        "Nothing was said, or nothing was heard": "没有人说话，或者没有听到声音",
        "Only the unconfirmed tail is shown here — the rest is already in the document": "这里只显示未确认的尾部 — 其余已在文档中",
        "Open Console": "打开控制台",
        "Open Settings": "打开设置",
        "Pasting is instant but replaces your clipboard for a moment. Typing works in apps that block paste, such as some terminals and remote desktops.": "粘贴是即时的，但会短暂占用剪贴板。逐字输入适用于禁止粘贴的应用，比如某些终端和远程桌面。",
        "Pasting it at once": "一次性粘贴",
        "Recording ended here — this Mac went to sleep.": "录制在此结束 — 这台 Mac 进入了睡眠。",
        "Remove “%@”": "移除「%@」",
        "Return sends · Shift-Return adds a line · Esc clears": "Return 发送 · Shift-Return 换行 · Esc 清空",
        "Show Floating Timer": "显示浮动计时器",
        "Start Recording a Meeting": "录制会议",
        "Still recognizing the previous dictation": "上一段听写仍在识别",
        "Still recognizing the previous dictation · %d words": "上一段听写仍在识别 · %d 个词",
        "Switched to %@": "已切换到 %@",
        "Tag filters combine with “and” — a meeting must carry every selected tag to appear.": "标签筛选以「与」组合 — 会议必须带有每个所选标签才会显示。",
        "The answer stopped. Your question is kept above — retry when the connection returns. Search and transcripts still work.": "回答已中断。你的问题保留在上方 — 网络恢复后重试。搜索和转录仍然可用。",
        "The recording ran, but no speech was recognized on either side. Usually this means the call audio was never captured — a browser tab without audio permission, or the wrong output device.": "录制进行了，但两边都没有识别到语音。通常这意味着通话音频从未被捕获 — 浏览器标签页没有音频权限，或输出设备不对。",
        "The saved key no longer works": "保存的密钥已失效",
        "The switch stays off until it is granted in System Settings › Privacy & Security › Calendars. Only event titles that overlap a recording are ever read.": "在 System Settings › Privacy & Security › Calendars 中授权之前，开关将保持关闭。只读取与录制时间重叠的事件标题。",
        "This Mac is offline": "这台 Mac 处于离线状态",
        "Too many questions at once": "一次提问太多",
        "Typing as you speak": "边说边输入",
        "Typing into %@ as you speak": "正在边说边输入到 %@",
        "Typing it out character by character": "逐字输入",
        "Your provider account is out of credit": "你的提供商账户余额不足",
        "Your provider is rate limiting. Wait a few seconds and retry — nothing was lost.": "提供商正在限制请求频率。等几秒后重试 — 没有丢失任何内容。",
        "macOS denied calendar access": "macOS 拒绝了日历访问",
        "API key": "API 密钥",
        "All Meetings": "所有会议",
        "Assistant": "助手",
        "Checking the key with %@. No transcript is sent — only a test request.": "正在向 %@ 验证密钥。不会发送任何转录 — 只是一次测试请求。",
        "Closing the window does not stop the recording. Stop it here, or from the menu bar at any time.": "关闭窗口不会停止录制。可在此处停止，或随时从菜单栏停止。",
        "Connect an assistant to answer questions": "连接助手来回答问题",
        "Dictate can record a browser call and keep the transcript on this Mac. Start one from the menu bar when your next call begins — you will be asked for consent once.": "Dictate 可以录制浏览器通话并把转录保存在这台 Mac 上。下次通话开始时从菜单栏启动 — 只会请求一次同意。",
        "Done": "完成",
        "Every change takes effect immediately.": "所有更改立即生效。",
        "Get one at %@.": "前往 %@ 获取。",
        "Hold a key, speak, let go. What you said is typed where your cursor is, in any app on this Mac.": "按住按键说话，松开即可。你说的话会输入到光标所在处，适用于这台 Mac 上的任何应用。",
        "Keys": "按键",
        "Languages": "语言",
        "Library": "资料库",
        "Paste a key from your own account.": "粘贴你自己账户的密钥。",
        "Saved to your Keychain, but not verified — this Mac is offline. It will be checked the first time you ask something.": "已存入钥匙串，但未验证 — 这台 Mac 处于离线状态。首次提问时会进行检查。",
        "Set Up Dictate": "设置 Dictate",
        "Stored in the macOS Keychain on this Mac. Never written to a settings file, never synced.": "保存在这台 Mac 的 macOS 钥匙串中。绝不写入设置文件，绝不同步。",
        "The key was refused. It may be revoked, from a different provider, or out of credit — the key itself was not saved.": "密钥被拒绝。它可能已被撤销、属于其他提供商或余额不足 — 密钥本身未被保存。",
        "Transcripts, search and quotes work without this. An assistant is only needed to write the answer.": "转录、搜索和引用无需此功能。助手仅用于撰写回答。",
        "Try Again": "重试",
        "Updates": "更新",
        "You pay your provider per question — typically a fraction of a cent. Only your question and the quoted passages are sent; recordings never leave this Mac.": "每个问题由你的提供商计费 — 通常不到一美分。只发送你的问题和引用的段落；录音绝不离开这台 Mac。",
        "Send": "发送",
        "Conversations": "对话",
        "New question": "新问题",
        "Deleted “%@”": "已删除“%@”",
        "Undo": "撤销",
        "Questions you ask are kept here so you can return to an answer.": "提出的问题会保存在这里，方便回看答案。",
        "Rename": "重命名",
        "Delete": "删除",
        "Voices are matched by sound — the name applies only to this voice's turns.": "声音按音色匹配——名称仅应用于该声音的发言。",
        "Call · voice %d": "通话 · 声音 %d",
        "Starred": "已加星标",
        "Other browser calls": "其他浏览器通话",
        "Sources": "来源",
        "Star meeting": "加星标",
        "Unstar meeting": "取消星标",
        "Export transcript…": "导出转录…",
        "Still recording": "仍在录制",
        "Got it": "知道了",
        "Call": "通话",
        "Dictating": "听写中",
        "Dictating in %@": "正在用%@听写",
        "Translating into English": "正在翻译成英语",
        "Translating into %@": "正在翻译成%@",
        "Release %@ to insert": "松开 %@ 即插入",
        "Also recording this meeting": "同时正在录制此会议",
        "%@ MB/s · about %@ left": "%@ MB/秒 · 剩余约 %@",
        "Not enough disk space: the download needs about %d MB and %d MB is free. Free up space and try again.": "磁盘空间不足：下载需要约 %d MB，可用仅 %d MB。请释放空间后重试。",
        "Fix…": "修复…",
        "Checked automatically · last %@": "自动检查 · 上次：%@",
        "Links": "链接",
        "Source code": "源代码",
        "Report an issue": "报告问题",
        "Finishing the transcript…": "正在完成转录…",
