        "That was very quiet — move closer to the microphone": "音がとても小さいです — マイクに近づいてください",
        "That was too loud — move back a little from the microphone": "音が大きすぎます — マイクから少し離れてください",
        "Sorry, I didn't catch that — could you say it again?": "すみません、聞き取れませんでした — もう一度お願いします",
        "Not inserted — text copied, press ⌘V to paste": "挿入されませんでした — テキストをコピー済み、⌘V で貼り付け",
        "Another app is using the microphone right now — close it and try again": "別のアプリがマイクを使用中です — 終了してからもう一度お試しください",
        "Shortcuts": "ショートカット",
        "General": "一般",
        "Status": "ステータス",
        "Type a key…": "キーを押す…",
        "Hold to talk, release to insert what you said.": "押している間は話し、離すと話した内容が入力されます。",
        "Version": "バージョン",
        "Downloaded %d of %d MB": "%d / %d MB をダウンロード済み",
        "Preparing the model for the Neural Engine… A few minutes, one time.": "Neural Engine 用にモデルを準備しています… 数分かかりますが、一度だけです。",
        "Warming up the model…": "モデルをウォームアップ中…",
        "Dictate is running from the downloaded image — drag it into Applications, eject the image, and launch it from there. Permissions granted to this temporary copy won't stick.": "Dictate はダウンロードしたイメージから起動されています。「アプリケーション」にドラッグし、イメージを取り出してからそこから起動してください。この一時コピーに与えた権限は保持されません。",
        "Still stuck? Reset the permission — this clears the broken macOS record, then grant the fresh request.": "まだ進めない？権限をリセットしてください。macOS の壊れた記録が消去されるので、新しいダイアログで許可し直してください。",
        "Words: %d · %.1f s": "単語数: %d · %.1f 秒",
        "Words: %d": "単語数: %d",
        "Cancelled": "キャンセルしました",
        "Changed your mind? Esc cancels the recording.": "気が変わったら Esc で録音をキャンセルできます。",
        "Network access: a one-time model download — nothing else. Don't take our word for it: turn off Wi-Fi and dictate.": "ネットワークアクセスはモデルの 1 回きりのダウンロードのみ。それ以外にはありません。言葉だけでは信じずに、Wi-Fi を切って音声入力してみてください。",
        "About Dictate": "Dictate について",
        // Onboarding — general
        "Welcome to Dictate": "Dictate へようこそ",
        "Back": "戻る",
        "Next": "次へ",
        "Step %d of %d": "ステップ %d / %d",
        // Welcome
        // Hotkey
        "Dictation key": "音声入力キー",
        "This key types characters — they'll end up in your text while you hold it. A modifier (Option, Cmd, Shift, Ctrl) or an F-key is safer.": "このキーは文字を入力します。押している間、その文字がテキストに混ざってしまいます。修飾キー（Option、Cmd、Shift、Ctrl）や F キーの方が安全です。",
        // Permissions
        "Microphone": "マイク",
        "Accessibility": "アクセシビリティ (Accessibility)",
        // Settings
        "Dictate Settings": "Dictate の設定",
        "This key types characters — they'll go into the text during dictation. A modifier or F-key is better.": "このキーは文字を入力します。音声入力中にテキストへ混ざってしまいます。修飾キーか F キーがおすすめです。",
        "Launch at login": "ログイン時に起動",
        "Show in Dock": "Dockに表示",
        "The agent searches and reads your transcripts on this Mac, and every answer names the meetings it drew from.": "エージェントはこの Mac 上で文字起こしを検索して読み、回答は根拠にしたミーティングを挙げます。",
        "Undo remove": "削除を取り消す",
        "Call started": "通話が始まりました",
        "Recording stopped by itself — the call ended.": "録音は自動的に停止しました — 通話が終了しました。",
        "Recording stopped by itself — ten minutes of silence.": "録音は自動的に停止しました — 10分間無音でした。",
        "%@ call started": "%@ の通話が始まりました",
        "Not this one": "今回は録音しない",
        "Record": "録音",
        "Record this call": "この通話を録音",
        "Dictation that works offline — recognition runs entirely on this Mac.": "オフラインで動く音声入力 — 認識はすべてこの Mac 上で行われます。",
        "Translation that works offline — speak your language, another comes out.": "オフラインで動く翻訳 — あなたの言語で話すと、別の言語で出てきます。",
        "Meetings, recorded and structured: speakers, summary, outline, search.": "ミーティングを記録し構造化：話者、要約、アウトライン、検索。",
        "An optional agent that knows your meetings — answers quote the moment they came from.": "ミーティングを知るオプションのエージェント — 回答は出典の瞬間を引用します。",
        "%d MB of %d MB": "%d MB / %d MB",
        "Already clicked and nothing changed?": "クリックしたのに何も変わらない場合",
        "Applications": "アプリケーション",
        "Downloading the speech model": "音声モデルをダウンロード中",
        "Grant…": "許可…",
        "Nothing here leaves this window. Two small things to try, then you are done.": "ここでの内容はこのウインドウの外に出ません。2 つの小さなお試しで完了です。",
        "Resume Download": "ダウンロードを再開",
        "Show me where to look": "確認する場所を見る",
        "Start Dictate when I log in — it appears in the Dock and the menu bar, and the Dock icon can be hidden later in Settings": "ログイン時に Dictate を起動 — Dock とメニューバーに表示されます。Dock アイコンはあとで設定から隠せます",
        "Start Using Dictate": "Dictate を使い始める",
        "Stopped · %d MB of %d MB kept on disk": "停止 · %d MB / %d MB をディスクに保持",
        "The connection was interrupted. Resuming continues from where it stopped — you will not download the whole %d MB again.": "接続が中断されました。再開すると止まったところから続きます — %d MB 全部をやり直す必要はありません。",
        "The download stopped at %d MB": "ダウンロードが %d MB で停止しました",
        "The model is being compiled for your chip so recognition is fast later. This takes a minute on first launch and never happens again.": "このチップ向けにモデルをコンパイルしています。あとの認識が速くなるためで、初回起動時に 1 分ほどかかり、二度と起こりません。",
        "This happens once. The model stays on your Mac and is the reason dictation works without an internet connection afterwards.": "これは一度だけです。モデルはこの Mac に残ります — だからこそ、その後の音声入力はインターネットなしで動きます。",
        "To hear you. Audio is processed on this Mac and discarded.": "あなたの声を聞くため。音声はこの Mac で処理され、破棄されます。",
        "To type the recognized text into the app you are using. It is the only way an app can insert text elsewhere.": "認識したテキストを使用中のアプリに入力するため。アプリが他のアプリにテキストを挿入できる唯一の方法です。",
        "Try it here first": "まずここで試す",
        "Two permissions from macOS": "macOS からの 2 つの許可",
        "macOS asks for these, not us. Dictate cannot work without both.": "これらを求めているのは macOS で、私たちではありません。両方ないと Dictate は動きません。",
        "Show or hide the conversations": "会話リストを表示/非表示",
        "Show or hide the sidebar": "サイドバーを表示/非表示",
        "Show or hide the meeting list": "ミーティングリストを表示/非表示",
        "Preparing the model for this Mac": "この Mac 用にモデルを準備中",
        "Not ready yet — this takes a few seconds after launch. Keep holding %@ and it will start.": "まだ準備中です — 起動後は数秒かかります。%@ を押し続けると始まります。",
        "Transcript text": "文字起こしのテキスト",
        "Smaller text": "小さい文字",
        "Standard text": "標準の文字",
        "Larger text": "大きい文字",
        "112 languages · from your system settings": "112言語 · システム設定から",
        "Add tag": "タグを追加",
        "Appearance": "外観",
        "Asked once. After this, recording starts from the menu bar without a prompt. Esc means don't record.": "確認は一度だけ。以降はメニューバーから確認なしで録音が始まります。Esc は録音しない、という意味です。",
        "Check for updates": "アップデートを確認",
        "Choose your keys and languages": "キーと言語を選ぶ",
        "Click, then press a key": "クリックしてからキーを押す",
        "Dark": "ダーク",
        "Dictate stays dark even when macOS switches. Every surface follows: the window, the dictation overlay, the recording pill and the menu.": "macOS が切り替わっても Dictate はダークのままです。ウインドウ、音声入力オーバーレイ、録音ピル、メニューのすべてが従います。",
        "Dictate stays light even when macOS switches. Every surface follows: the window, the dictation overlay, the recording pill and the menu.": "macOS が切り替わっても Dictate はライトのままです。ウインドウ、音声入力オーバーレイ、録音ピル、メニューのすべてが従います。",
        "Dictate will record your microphone and the audio from the call, and keep the transcript on this Mac. Recording other people may require their consent where you are.": "Dictate はマイクと通話の音声を録音し、文字起こしをこの Mac に保存します。他の人を録音するには、地域によっては相手の同意が必要です。",
        "Don't Record": "録音しない",
        "Follows the macOS setting, switching with it at sunset. Choose Light or Dark to hold Dictate to one appearance regardless of the system.": "macOS の設定に従い、日没とともに切り替わります。ライトまたはダークを選ぶと、システムに関係なく Dictate の外観を固定できます。",
        "Hold the key while you speak. Anything can be changed later in Settings.": "話している間はキーを押し続けてください。あとで設定からいつでも変更できます。",
        "I speak": "話す言語",
        "Light": "ライト",
        "Looking through %d meetings…": "%d 件のミーティングを確認中…",
        "Match system": "システムに合わせる",
        "Modifier keys work best: they never insert a character when you hold them. Esc always cancels a dictation in progress.": "修飾キーが最適です。押し続けても文字が入力されません。Esc はいつでも進行中の音声入力をキャンセルします。",
        "Reading “%@”…": "「%@」を読んでいます…",
        "Record this call?": "この通話を録音しますか？",
        "Searching your meetings…": "ミーティングを検索中…",
        "Start Recording": "録音を開始",
        "Tags": "タグ",
        "Voices": "声",
        "Summary": "要約",
        "Outline": "アウトライン",
        "Hide outline": "アウトラインを隠す",
        "Show outline": "アウトラインを表示",
        "two levels": "2 階層",
        "three levels": "3 階層",
        "%d moments": "%d 個のモーメント",
        "Kept on this Mac. Deleting is immediate; beyond 50 conversations the oldest age out.": "この Mac に保存されます。削除は即時で、50 件を超えると古い会話から消えます。",
        "Ask across all meetings…": "すべてのミーティングに質問…",
        "Recently Added": "最近追加",
        "%d meetings · %d h of audio": "%d 件のミーティング · 音声 %d 時間",
        "%d meetings · %d min of audio": "%d 件のミーティング · 音声 %d 分",
        "Show more": "もっと見る",
        "Try one of these": "これらを試してみてください",
        "Accessibility access is turned off": "アクセシビリティのアクセスがオフです",
        "Dictation can hear you but cannot type. Re-enable it to continue.": "音声入力は聞こえていますが、入力できません。再度有効にしてください。",
        "Recent dictations": "最近の音声入力",
        "Secure input is active — the hotkey cannot work": "セキュア入力が有効 — ホットキーは機能できません",
        "Something has a password field focused. macOS does not say which app. Click into an ordinary text field and dictation works again.": "どこかのアプリでパスワード欄がフォーカスされています。macOS はどのアプリかを教えません。普通のテキスト欄をクリックすれば再び機能します。",
        "Start Recording Meeting": "ミーティングを録音",
        "Stop Recording Meeting": "ミーティングの録音を停止",
        "click to copy": "クリックでコピー",
        "dictate in %@": "%@で音声入力",
        "dictate in any language": "任意の言語で音声入力",
        "translate %@ → %@": "%@ → %@ に翻訳",
        "translate into %@": "%@ に翻訳",
        "%d waiting": "%d 件待機中",
        "%d words typed": "%d 語入力済み",
        "Add a Key…": "キーを追加…",
        "Both will be inserted in the order you spoke them": "2つとも話した順に挿入されます",
        "Check Audio Setup": "オーディオ設定を確認",
        "Clear All Filters": "すべてのフィルタを解除",
        "F-keys can also trigger a system control (brightness, media) — macOS will do both. To use one as a plain key, turn on “Use F1, F2, etc. as standard function keys” in Keyboard settings.": "Fキーはシステム操作（輝度・メディア）も兼ねています — macOS は両方を実行します。通常のキーとして使うには、キーボード設定で「Use F1, F2, etc. as standard function keys」をオンにしてください。",
        "How this works": "仕組み",
        "Input device changed": "入力デバイスが変わりました",
        "Insert text by": "テキストの挿入方法",
        "It was revoked or replaced since you connected. It has been removed from the Keychain — nothing was retried with it.": "接続後に失効または差し替えられています。キーチェーンから削除しました — このキーで再送信は行っていません。",
        "Join a call in the browser, then start recording. Dictate captures your microphone and the call audio, transcribes both on this Mac, and keeps the transcript here. Nothing is uploaded.": "ブラウザで通話に参加し、録音を開始してください。Dictate はマイクと通話音声を取り込み、両方をこの Mac 上で文字起こしし、ここに保存します。何もアップロードされません。",
        "No meeting has all of these tags": "これらのタグをすべて持つミーティングはありません",
        "No meeting has this tag": "このタグを持つミーティングはありません",
        "Nothing was said, or nothing was heard": "何も話されなかったか、何も聞こえませんでした",
        "Only the unconfirmed tail is shown here — the rest is already in the document": "ここには未確定の末尾だけが表示されます — 残りはすでに書類の中にあります",
        "Open Console": "コンソールを開く",
        "Open Settings": "設定を開く",
        "Pasting is instant but replaces your clipboard for a moment. Typing works in apps that block paste, such as some terminals and remote desktops.": "ペーストは瞬時ですが、一瞬クリップボードを使います。タイプ入力は、ペーストを受け付けない一部のターミナルやリモートデスクトップでも機能します。",
        "Pasting it at once": "一括でペースト",
        "Recording ended here — this Mac went to sleep.": "録音はここで終了 — この Mac はスリープしました。",
        "Remove “%@”": "「%@」を外す",
        "Return sends · Shift-Return adds a line · Esc clears": "Return で送信 · Shift-Return で改行 · Esc でクリア",
        "Show Floating Timer": "フローティングタイマーを表示",
        "Start Recording a Meeting": "ミーティングを録音",
        "Still recognizing the previous dictation": "前の音声入力をまだ認識中",
        "Still recognizing the previous dictation · %d words": "前の音声入力をまだ認識中 · %d 語",
        "Switched to %@": "%@ に切り替わりました",
        "Tag filters combine with “and” — a meeting must carry every selected tag to appear.": "タグフィルタは「かつ」で組み合わされます — 選んだタグをすべて持つミーティングだけが表示されます。",
        "The answer stopped. Your question is kept above — retry when the connection returns. Search and transcripts still work.": "回答が途中で止まりました。質問は上に残っています — 接続が戻ったら再試行してください。検索と文字起こしは使えます。",
        "The recording ran, but no speech was recognized on either side. Usually this means the call audio was never captured — a browser tab without audio permission, or the wrong output device.": "録音は行われましたが、どちら側の音声も認識されませんでした。多くの場合、通話音声が取り込まれていません — 音声権限のないブラウザタブか、出力デバイスの誤りです。",
        "The saved key no longer works": "保存されたキーが使えなくなりました",
        "The switch stays off until it is granted in System Settings › Privacy & Security › Calendars. Only event titles that overlap a recording are ever read.": "System Settings › Privacy & Security › Calendars で許可されるまでスイッチはオフのままです。読み取るのは録音と重なるイベントのタイトルだけです。",
        "This Mac is offline": "この Mac はオフラインです",
        "Too many questions at once": "一度に質問が多すぎます",
        "Typing as you speak": "話しながら入力中",
        "Typing into %@ as you speak": "話しながら %@ に入力中",
        "Typing it out character by character": "一文字ずつタイプ",
        "Your provider account is out of credit": "プロバイダのアカウントのクレジットが不足しています",
        "Your provider is rate limiting. Wait a few seconds and retry — nothing was lost.": "プロバイダがレート制限中です。数秒待って再試行してください — 何も失われていません。",
        "macOS denied calendar access": "macOS がカレンダーへのアクセスを拒否しました",
        "API key": "APIキー",
        "All Meetings": "すべてのミーティング",
        "Assistant": "アシスタント",
        "Checking the key with %@. No transcript is sent — only a test request.": "%@ でキーを確認しています。文字起こしは送信されません — テストリクエストのみです。",
        "Closing the window does not stop the recording. Stop it here, or from the menu bar at any time.": "ウインドウを閉じても録音は止まりません。ここで停止するか、いつでもメニューバーから停止できます。",
        "Connect an assistant to answer questions": "アシスタントを接続して質問に答える",
        "Dictate can record a browser call and keep the transcript on this Mac. Start one from the menu bar when your next call begins — you will be asked for consent once.": "Dictate はブラウザ通話を録音し、文字起こしをこの Mac に保存できます。次の通話が始まったらメニューバーから開始してください — 同意は一度だけ求められます。",
        "Done": "完了",
        "Every change takes effect immediately.": "変更はすべて即座に反映されます。",
        "Get one at %@.": "%@ で取得できます。",
        "Hold a key, speak, let go. What you said is typed where your cursor is, in any app on this Mac.": "キーを押しながら話し、離すだけ。話した内容が、この Mac のどのアプリでもカーソルの位置に入力されます。",
        "Keys": "キー",
        "Languages": "言語",
        "Library": "ライブラリ",
        "Paste a key from your own account.": "自分のアカウントのキーを貼り付けてください。",
        "Saved to your Keychain, but not verified — this Mac is offline. It will be checked the first time you ask something.": "キーチェーンに保存されましたが未確認です — この Mac はオフラインです。最初の質問時に確認されます。",
        "Set Up Dictate": "Dictate を設定",
        "Stored in the macOS Keychain on this Mac. Never written to a settings file, never synced.": "この Mac の macOS キーチェーンに保存されます。設定ファイルに書き込まれることも、同期されることもありません。",
        "The key was refused. It may be revoked, from a different provider, or out of credit — the key itself was not saved.": "キーが拒否されました。失効している、別のプロバイダのもの、またはクレジット切れの可能性があります — キー自体は保存されていません。",
        "Transcripts, search and quotes work without this. An assistant is only needed to write the answer.": "文字起こし・検索・引用はこれなしで動作します。アシスタントは回答を書くためだけに必要です。",
        "Try Again": "再試行",
        "Updates": "アップデート",
        "You pay your provider per question — typically a fraction of a cent. Only your question and the quoted passages are sent; recordings never leave this Mac.": "質問ごとにプロバイダへ支払います — 通常は1セント未満です。送信されるのは質問と引用箇所のみで、録音がこの Mac の外に出ることはありません。",
        "Send": "送信",
        "Conversations": "会話",
        "New question": "新しい質問",
        "Deleted “%@”": "「%@」を削除しました",
        "Undo": "取り消す",
        "Questions you ask are kept here so you can return to an answer.": "質問はここに保存され、回答にいつでも戻れます。",
        "Rename": "名称変更",
        "Delete": "削除",
        "Voices are matched by sound — the name applies only to this voice's turns.": "声は音で照合されます — 名前はこの声の発言にのみ適用されます。",
        "Call · voice %d": "通話 · 声 %d",
        "Starred": "スター付き",
        "Other browser calls": "その他のブラウザ通話",
        "Sources": "ソース",
        "Star meeting": "スターを付ける",
        "Unstar meeting": "スターを外す",
        "Export transcript…": "文字起こしを書き出す…",
        "Still recording": "録音は継続中",
        "Got it": "了解",
        "Call": "通話",
        "Dictating": "音声入力中",
        "Dictating in %@": "%@で音声入力中",
        "Translating into English": "英語に翻訳中",
        "Translating into %@": "%@に翻訳中",
        "Release %@ to insert": "%@を離すと挿入",
        "Also recording this meeting": "このミーティングも録音中です",
        "%@ MB/s · about %@ left": "%@ MB/秒 · 残り約%@",
        "Not enough disk space: the download needs about %d MB and %d MB is free. Free up space and try again.": "ディスク空き容量が不足：ダウンロードには約%d MB必要ですが、空きは%d MBです。空き容量を確保して再試行してください。",
        "Fix…": "修正…",
        "Checked automatically · last %@": "自動チェック · 前回: %@",
        "Links": "リンク",
