        "System audio recording is not allowed. Enable Dictate in System Settings → Privacy & Security → Screen & System Audio Recording, then try again.": "시스템 오디오 녹음이 허용되지 않았습니다. 시스템 설정 → 개인정보 보호 및 보안 → 화면 및 시스템 오디오 녹음에서 Dictate를 활성화한 뒤 다시 시도하세요.",
