        "Translate key": "번역 키",
        "%@ is using the microphone right now — close it and try again": "%@에서 지금 마이크를 사용 중입니다 — 종료한 뒤 다시 시도하세요",
        "That was very quiet — move closer to the microphone": "소리가 너무 작습니다 — 마이크에 더 가까이 오세요",
        "That was too loud — move back a little from the microphone": "소리가 너무 큽니다 — 마이크에서 조금 떨어지세요",
        "Sorry, I didn't catch that — could you say it again?": "죄송해요, 잘 못 들었어요 — 다시 한 번 말씀해 주세요",
        "Not inserted — text copied, press ⌘V to paste": "삽입되지 않음 — 텍스트 복사됨, ⌘V로 붙여넣기",
        "Another app is using the microphone right now — close it and try again": "다른 앱이 마이크를 사용 중입니다 — 종료한 후 다시 시도하세요",
        "Shortcuts": "단축키",
        "General": "일반",
        "Status": "상태",
        "Type a key…": "키를 누르세요…",
