        "Recognition runs on your Mac's Neural Engine — Whisper large-v3-turbo: 112 languages, great with accents, fast enough for live text. Translation runs on this Mac too. Your voice never leaves this computer.": "인식은 Mac의 Neural Engine에서 실행됩니다 — Whisper large-v3-turbo: 112개 언어, 억양에도 강하고 실시간 텍스트를 보여줄 만큼 빠릅니다. 번역도 이 Mac에서 이루어집니다. 당신의 목소리는 이 컴퓨터를 떠나지 않습니다.",
