    static let vi: [String: String] = [
        "Settings": "Cài đặt",
        "Keyboard shortcuts": "Phím tắt bàn phím",
        "Storage & models": "Lưu trữ và mô hình",
        "Asking is the one thing that leaves this Mac: your question, the search hits, and the transcripts the agent opens to answer go to %@ on your key. Nothing is sent until you ask.": "Hỏi là thứ duy nhất rời khỏi máy Mac này: câu hỏi của bạn, các kết quả tìm kiếm và những bản ghi chép mà tác nhân mở để trả lời sẽ đến %@ bằng khóa của bạn. Không gì được gửi cho đến khi bạn hỏi.",
        "The Keychain refused to save the key — it stays in the field. Try again after unlocking the keychain.": "Keychain từ chối lưu khóa — khóa vẫn còn trong ô. Mở khóa keychain rồi thử lại.",
        "Couldn't reach the update server. Try again once you're online.": "Không thể kết nối máy chủ cập nhật. Thử lại khi có mạng.",
        "Update %@ is on its way — downloading now, it installs itself soon.": "Bản cập nhật %@ đang trên đường đến — đang tải xuống, sẽ tự cài đặt sớm.",
        "You're up to date — Dictate %@ is the newest version.": "Bạn đang dùng bản mới nhất — Dictate %@ là phiên bản mới nhất.",
        "Recorded meetings appear here.": "Các cuộc họp đã ghi sẽ xuất hiện ở đây.",
        "This is your microphone only — the other side of the call was not recorded and cannot be recovered.": "Đây chỉ là micrô của bạn — phía bên kia của cuộc gọi không được ghi âm và không thể khôi phục.",
        "Turning both on covers the calls that come next.": "Bật cả hai sẽ bao trọn các cuộc gọi tiếp theo.",
        "%@ refused the request for billing reasons. Add credit in your provider account, or disconnect the agent in Settings.": "%@ đã từ chối yêu cầu vì lý do thanh toán. Nạp thêm tín dụng vào tài khoản nhà cung cấp, hoặc ngắt kết nối tác nhân trong Cài đặt.",
        "Agent": "Tác nhân",
        "Ask your agent": "Hỏi tác nhân",
        "Ask your agent anything…": "Hỏi tác nhân của bạn bất cứ điều gì…",
        "Has read %d of %d meetings": "Đã đọc %d trong %d cuộc họp",
        "Has read 1 meeting": "Đã đọc 1 cuộc họp",
        "Has read all %d meetings": "Đã đọc cả %d cuộc họp",
        "Meetings & Agent…": "Cuộc họp & Tác nhân…",
        "Not now keeps the agent off and hidden. Search and transcripts are unaffected.": "Để sau sẽ giữ tác nhân tắt và ẩn. Tìm kiếm và bản ghi chép không bị ảnh hưởng.",
        "Nothing to read yet": "Chưa có gì để đọc",
        "Off — has read nothing yet": "Đang tắt — chưa đọc gì",
        "Questions are never limited to one meeting. Your agent searches everything you have recorded and the answer names the meeting and the person.": "Câu hỏi không bao giờ giới hạn trong một cuộc họp. Tác nhân tìm trong mọi thứ bạn đã ghi và câu trả lời nêu tên cuộc họp cùng người nói.",
        "Reading %d of %d meetings…": "Đang đọc %d trong %d cuộc họp…",
        "The agent uses": "Tác nhân dùng",
        "This is what writes the summary and the outline, and what gives your agent something to answer from. Off, you get the raw transcript — no summary, no outline, and no agent. Nothing is sent anywhere either way.": "Đây là thứ viết tóm tắt và dàn ý, và cho tác nhân thứ để trả lời. Tắt, bạn chỉ có bản ghi thô — không tóm tắt, không dàn ý, không tác nhân. Dù thế nào cũng không có gì được gửi đi đâu.",
        "Your agent answers questions across everything you have recorded — “what did we decide about the freeze date” — and cites the meeting and moment it came from. It needs the model that reads your meetings, which is currently off. Nothing leaves this Mac either way.": "Tác nhân trả lời các câu hỏi về mọi thứ bạn đã ghi — “chúng ta đã quyết gì về ngày chốt” — và nêu rõ cuộc họp cùng thời điểm chứa câu trả lời. Nó cần mô hình đọc các cuộc họp của bạn, hiện đang tắt. Dù thế nào, không có gì rời khỏi máy Mac này.",
        "Your agent has nothing to read yet": "Tác nhân của bạn chưa có gì để đọc",
        "Your agent has read 1 meeting": "Tác nhân của bạn đã đọc 1 cuộc họp",
        "Your agent has read all %d meetings": "Tác nhân của bạn đã đọc cả %d cuộc họp",
        "Your agent is off": "Tác nhân của bạn đang tắt",
        "Your agent is reading — %d of %d meetings so far": "Tác nhân đang đọc — hiện %d trong %d cuộc họp",
        "answers with %@": "trả lời bằng %@",
        "Nothing here can hear a call until it is granted in System Settings › Privacy & Security › Microphone.": "Không gì ở đây có thể nghe cuộc gọi cho đến khi được cấp quyền trong Cài đặt Hệ thống › Quyền riêng tư & Bảo mật › Micrô.",
        "There is no summary or outline — reading your meetings is off.": "Không có tóm tắt hay dàn ý — tính năng đọc cuộc họp đang tắt.",
        "This is your microphone only — the other side of the call is missing, the text is one unbroken block, and there is no summary or outline.": "Đây chỉ là micrô của bạn — thiếu phía bên kia của cuộc gọi, văn bản là một khối liền, và không có tóm tắt hay dàn ý.",
        "Turn both on": "Bật cả hai",
        "Turn it on": "Bật lên",
        "Turning it on also writes them for the recordings that come next. Writing one now leaves the switch off.": "Bật lên thì các bản ghi sau cũng sẽ được viết. Viết ngay bây giờ vẫn giữ công tắc tắt.",
        "Waiting on microphone access.": "Đang chờ quyền truy cập micrô.",
        "Waits for “%@” above — there is no call audio to separate yet.": "Chờ “%@” ở trên — chưa có âm thanh cuộc gọi để tách.",
        "Write one, this once": "Viết một bản, chỉ lần này",
        "Writing one now reads only this transcript and leaves the switches off. The other side of this call was not recorded and cannot be recovered.": "Viết ngay bây giờ chỉ đọc bản ghi chép này và giữ nguyên các công tắc tắt. Phía bên kia của cuộc gọi này không được ghi âm và không thể khôi phục.",
        "Writing…": "Đang viết…",
        "macOS denied microphone access": "macOS đã từ chối quyền truy cập micrô",
        "%@ call — not being recorded": "Cuộc gọi %@ — không được ghi âm",
        "Asked once. After this, the panel is the short version above.": "Chỉ hỏi một lần. Sau lần này, bảng sẽ là bản ngắn như ở trên.",
        "Call recording is off, so this one is passing untranscribed. Turning it on gives you a searchable transcript and a summary afterwards, kept on this Mac.": "Ghi âm cuộc gọi đang tắt, nên cuộc này sẽ trôi qua không có bản ghi. Bật lên để sau cuộc gọi có bản ghi chép tìm kiếm được và bản tóm tắt, lưu trên máy Mac này.",
        "Call — not being recorded": "Cuộc gọi — không được ghi âm",
        "Calls are not noticed automatically. You can start each one here, or let Dictate offer when a call begins.": "Các cuộc gọi không được tự động nhận biết. Bạn có thể bắt đầu từng cuộc tại đây, hoặc để Dictate đề nghị khi cuộc gọi bắt đầu.",
        "Connect a provider…": "Kết nối nhà cung cấp…",
        "Dictation still works. Each switch below says what it adds; you can turn on one and leave the rest alone.": "Đọc chính tả vẫn hoạt động. Mỗi công tắc bên dưới cho biết nó thêm gì; bạn có thể bật một cái và để yên phần còn lại.",
        "Dictation works already — hold the dictation key and speak anywhere. Everything below is about meetings, and none of it is required. Turn on what you want; the rest stays off.": "Đọc chính tả đã hoạt động — giữ phím đọc chính tả và nói ở bất cứ đâu. Mọi thứ bên dưới là về cuộc họp, và không có gì bắt buộc. Bật thứ bạn muốn; phần còn lại vẫn tắt.",
        "Don't offer this again": "Đừng đề nghị nữa",
        "Everything here is off, so calls pass unnoticed": "Mọi thứ ở đây đang tắt, nên các cuộc gọi trôi qua không ai hay",
        "Let the model read your meetings": "Cho mô hình đọc các cuộc họp của bạn",
        "Not watching for calls": "Không theo dõi cuộc gọi",
        "Notice when a call starts": "Nhận biết khi cuộc gọi bắt đầu",
        "Off, a recording holds your microphone only — your half of the conversation, in one unbroken block. On, both sides are transcribed as named turns.": "Tắt, bản ghi chỉ có micrô của bạn — nửa cuộc trò chuyện của bạn, trong một khối liền. Bật, cả hai phía được ghi chép thành lượt nói có tên.",
        "Off, you get only your own microphone — your half of the conversation. On, the other side is transcribed as well.": "Tắt, bạn chỉ có micrô của mình — nửa cuộc trò chuyện của bạn. Bật, phía bên kia cũng được ghi chép.",
        "On": "Bật",
        "Or leave this and set them up later in Settings.": "Hoặc để đó và thiết lập sau trong Cài đặt.",
        "Read meeting names from Calendar": "Đọc tên cuộc họp từ Lịch",
        "Record the call audio too": "Ghi cả âm thanh cuộc gọi",
        "Record the call audio, and separate the voices": "Ghi âm thanh cuộc gọi và tách giọng nói",
        "Recordings arrive already titled instead of as “Zoom call, 14:02”. Only titles overlapping a recording are read.": "Bản ghi đến với tiêu đề sẵn, thay vì “Cuộc gọi Zoom, 14:02”. Chỉ đọc các tiêu đề trùng thời gian với bản ghi.",
        "Separate the voices": "Tách giọng nói",
        "Set up calls…": "Thiết lập cuộc gọi…",
        "The agent searches and reads your transcripts on this Mac; the written answer comes from a provider you connect with your own key.": "Trợ lý tìm và đọc bản ghi chép trên máy Mac này; câu trả lời viết ra đến từ nhà cung cấp bạn kết nối bằng khóa của riêng mình.",
        "Three things are off. Here is what each one adds.": "Ba thứ đang tắt. Đây là những gì mỗi thứ mang lại.",
        "Turn all on": "Bật tất cả",
        "Turn all three on": "Bật cả ba",
        "Turn on": "Bật",
        "Turn on reading": "Bật đọc",
        "Turns one block of text into named turns, so you can see who committed to what. Names are yours to set and can be changed after the fact.": "Biến một khối văn bản thành các lượt nói có tên, để thấy ai đã cam kết điều gì. Tên do bạn đặt và có thể đổi về sau.",
        "Watching for calls": "Đang theo dõi cuộc gọi",
        "What it does": "Nó làm gì",
        "With this on, a small panel appears when a call starts and you decide there — no need to remember to start anything.": "Bật lên, một bảng nhỏ xuất hiện khi cuộc gọi bắt đầu và bạn quyết định tại đó — không cần nhớ phải khởi động gì.",
        "listening": "đang nghe",
        "Back to the top": "Về đầu",
        "Show everything tagged #%@": "Hiện mọi thứ gắn thẻ #%@",
        "Remove #%@ from this meeting": "Bỏ #%@ khỏi cuộc họp này",
        "Tag": "Thẻ",
        "Create #%@": "Tạo #%@",
        "Show Live Transcript": "Hiện bản ghi đang chạy",
