        "Add your OpenAI API key in Settings to ask questions": "Thêm khóa API OpenAI trong Cài đặt để đặt câu hỏi",
        "The model refused the request (%@)": "Mô hình đã từ chối yêu cầu (%@)",
        "Reading…": "Đang đọc…",
        "The agent could answer this — connect Claude or ChatGPT.": "Tác nhân có thể trả lời — hãy kết nối Claude hoặc ChatGPT.",
        "Connect": "Kết nối",
