        "System audio recording is not allowed. Enable Dictate in System Settings → Privacy & Security → Screen & System Audio Recording, then try again.": "Chưa cho phép ghi âm thanh hệ thống. Hãy bật Dictate trong Cài đặt Hệ thống → Quyền riêng tư & Bảo mật → Ghi màn hình và âm thanh hệ thống, rồi thử lại.",
        "Stop": "Dừng",
