        "No language matches your search.": "Không có ngôn ngữ nào khớp.",
        "Translate key": "Phím dịch",
        "%@ is using the microphone right now — close it and try again": "%@ đang dùng micrô — hãy đóng ứng dụng đó rồi thử lại",
        "That was very quiet — move closer to the microphone": "Âm thanh quá nhỏ — hãy lại gần micrô hơn",
        "That was too loud — move back a little from the microphone": "Âm thanh quá to — hãy lùi ra xa micrô một chút",
        "Sorry, I didn't catch that — could you say it again?": "Xin lỗi, tôi chưa nghe rõ — bạn nói lại được không?",
        "Not inserted — text copied, press ⌘V to paste": "Chưa chèn — văn bản đã sao chép, nhấn ⌘V để dán",
        "Another app is using the microphone right now — close it and try again": "Một ứng dụng khác đang dùng micrô — hãy đóng nó và thử lại",
        "Shortcuts": "Phím tắt",
        "General": "Chung",
        "Status": "Trạng thái",
        "Type a key…": "Nhấn một phím…",
        "Hold to talk, release to insert what you said.": "Giữ để nói, thả để chèn nội dung bạn vừa nói.",
        "Version": "Phiên bản",
        "Downloaded %d of %d MB": "Đã tải %d / %d MB",
        "Preparing the model for the Neural Engine… A few minutes, one time.": "Đang chuẩn bị mô hình cho Neural Engine… Vài phút, chỉ một lần.",
        "Warming up the model…": "Đang khởi động mô hình…",
        "Dictate is running from the downloaded image — drag it into Applications, eject the image, and launch it from there. Permissions granted to this temporary copy won't stick.": "Dictate đang chạy từ tệp ảnh đã tải về — hãy kéo nó vào «Ứng dụng», đẩy tệp ảnh ra rồi mở từ đó. Quyền cấp cho bản sao tạm thời này sẽ không được giữ lại.",
        "Still stuck? Reset the permission — this clears the broken macOS record, then grant the fresh request.": "Vẫn kẹt? Đặt lại quyền — thao tác này xóa bản ghi hỏng của macOS, sau đó hãy cấp quyền trong hộp thoại mới.",
        "Words: %d · %.1f s": "Số từ: %d · %.1f giây",
