        "Dictation key": "Phím đọc chính tả",
        "This key types characters — they'll end up in your text while you hold it. A modifier (Option, Cmd, Shift, Ctrl) or an F-key is safer.": "Phím này gõ ra ký tự — chúng sẽ lọt vào văn bản khi bạn giữ phím. Chọn phím bổ trợ (Option, Cmd, Shift, Ctrl) hoặc phím F sẽ an toàn hơn.",
