        "This key types characters — they'll go into the text during dictation. A modifier or F-key is better.": "Phím này gõ ra ký tự — chúng sẽ lọt vào văn bản trong lúc đọc chính tả. Nên dùng phím bổ trợ hoặc phím F.",
        "Launch at login": "Chạy khi đăng nhập",
        "Show in Dock": "Hiển thị trong Dock",
        "The agent searches and reads your transcripts on this Mac, and every answer names the meetings it drew from.": "Trợ lý tìm và đọc bản ghi của bạn trên máy Mac này, và mỗi câu trả lời nêu tên các cuộc họp nó dựa vào.",
        "Undo remove": "Hoàn tác xóa",
