        "Not this one": "Không phải cuộc này",
        "Record": "Ghi âm",
        "Record this call": "Ghi âm cuộc gọi này",
        "Dictation that works offline — recognition runs entirely on this Mac.": "Đọc chính tả hoạt động ngoại tuyến — nhận dạng diễn ra hoàn toàn trên máy Mac này.",
        "Translation that works offline — speak your language, another comes out.": "Dịch hoạt động ngoại tuyến — nói ngôn ngữ của bạn, ra ngôn ngữ khác.",
        "Meetings, recorded and structured: speakers, summary, outline, search.": "Cuộc họp được ghi và cấu trúc: người nói, tóm tắt, dàn ý, tìm kiếm.",
        "An optional agent that knows your meetings — answers quote the moment they came from.": "Một trợ lý tùy chọn hiểu các cuộc họp của bạn — câu trả lời trích dẫn khoảnh khắc nó lấy ra.",
        "%d MB of %d MB": "%d MB trên %d MB",
        "Already clicked and nothing changed?": "Đã bấm mà không có gì thay đổi?",
        "Applications": "Ứng dụng",
        "Downloading the speech model": "Đang tải mô hình giọng nói",
        "Grant…": "Cấp…",
        "Nothing here leaves this window. Two small things to try, then you are done.": "Không gì rời khỏi cửa sổ này. Hai việc nhỏ để thử, rồi bạn xong.",
        "Resume Download": "Tiếp tục tải",
        "Show me where to look": "Chỉ tôi chỗ cần xem",
        "Start Dictate when I log in — it appears in the Dock and the menu bar, and the Dock icon can be hidden later in Settings": "Khởi động Dictate khi tôi đăng nhập — nó xuất hiện trong Dock và thanh menu; biểu tượng Dock có thể ẩn sau trong Cài đặt",
        "Start Using Dictate": "Bắt đầu dùng Dictate",
        "Stopped · %d MB of %d MB kept on disk": "Đã dừng · %d MB trên %d MB được giữ trên đĩa",
        "The connection was interrupted. Resuming continues from where it stopped — you will not download the whole %d MB again.": "Kết nối bị gián đoạn. Tiếp tục sẽ bắt đầu từ chỗ dừng — bạn sẽ không tải lại toàn bộ %d MB.",
        "The download stopped at %d MB": "Tải xuống dừng ở %d MB",
        "The model is being compiled for your chip so recognition is fast later. This takes a minute on first launch and never happens again.": "Mô hình đang được biên dịch cho chip của bạn để nhận dạng nhanh về sau. Mất một phút ở lần khởi động đầu và không bao giờ lặp lại.",
        "This happens once. The model stays on your Mac and is the reason dictation works without an internet connection afterwards.": "Điều này chỉ xảy ra một lần. Mô hình ở lại trên máy Mac — đó là lý do đọc chính tả sau này hoạt động không cần internet.",
        "To hear you. Audio is processed on this Mac and discarded.": "Để nghe bạn. Âm thanh được xử lý trên máy Mac này và bị loại bỏ.",
        "To type the recognized text into the app you are using. It is the only way an app can insert text elsewhere.": "Để gõ văn bản đã nhận dạng vào ứng dụng bạn đang dùng. Đó là cách duy nhất một ứng dụng chèn văn bản vào nơi khác.",
        "Try it here first": "Thử ở đây trước",
        "Two permissions from macOS": "Hai quyền từ macOS",
        "macOS asks for these, not us. Dictate cannot work without both.": "macOS hỏi những quyền này, không phải chúng tôi. Thiếu một trong hai, Dictate không hoạt động.",
        "Show or hide the conversations": "Hiện hoặc ẩn các cuộc trò chuyện",
        "Show or hide the sidebar": "Hiện hoặc ẩn thanh bên",
        "Show or hide the meeting list": "Hiện hoặc ẩn danh sách cuộc họp",
        "Preparing the model for this Mac": "Đang chuẩn bị mô hình cho máy Mac này",
        "Not ready yet — this takes a few seconds after launch. Keep holding %@ and it will start.": "Chưa sẵn sàng — mất vài giây sau khi khởi động. Giữ %@ và nó sẽ bắt đầu.",
        "Transcript text": "Chữ bản ghi",
        "Smaller text": "Chữ nhỏ hơn",
        "Standard text": "Chữ tiêu chuẩn",
        "Larger text": "Chữ lớn hơn",
        "112 languages · from your system settings": "112 ngôn ngữ · từ cài đặt hệ thống",
        "Add tag": "Thêm thẻ",
        "Appearance": "Giao diện",
        "Asked once. After this, recording starts from the menu bar without a prompt. Esc means don't record.": "Chỉ hỏi một lần. Sau đó, ghi âm bắt đầu từ thanh menu mà không hỏi lại. Esc nghĩa là không ghi âm.",
        "Check for updates": "Kiểm tra bản cập nhật",
        "Choose your keys and languages": "Chọn phím và ngôn ngữ của bạn",
        "Click, then press a key": "Bấm vào đây, rồi nhấn một phím",
        "Dark": "Tối",
        "Dictate stays dark even when macOS switches. Every surface follows: the window, the dictation overlay, the recording pill and the menu.": "Dictate giữ giao diện tối ngay cả khi macOS chuyển đổi. Mọi bề mặt đều theo: cửa sổ, lớp phủ đọc chính tả, viên ghi âm và menu.",
        "Dictate stays light even when macOS switches. Every surface follows: the window, the dictation overlay, the recording pill and the menu.": "Dictate giữ giao diện sáng ngay cả khi macOS chuyển đổi. Mọi bề mặt đều theo: cửa sổ, lớp phủ đọc chính tả, viên ghi âm và menu.",
        "Dictate will record your microphone and the audio from the call, and keep the transcript on this Mac. Recording other people may require their consent where you are.": "Dictate sẽ ghi âm micrô của bạn và âm thanh cuộc gọi, và giữ bản ghi trên máy Mac này. Ghi âm người khác có thể cần sự đồng ý của họ tùy nơi bạn ở.",
        "Don't Record": "Không ghi âm",
        "Follows the macOS setting, switching with it at sunset. Choose Light or Dark to hold Dictate to one appearance regardless of the system.": "Theo cài đặt của macOS, chuyển đổi cùng nó lúc hoàng hôn. Chọn Sáng hoặc Tối để giữ Dictate ở một giao diện bất kể hệ thống.",
        "Hold the key while you speak. Anything can be changed later in Settings.": "Giữ phím trong khi nói. Mọi thứ có thể thay đổi sau trong Cài đặt.",
        "I speak": "Tôi nói",
        "Light": "Sáng",
        "Looking through %d meetings…": "Đang xem %d cuộc họp…",
        "Match system": "Theo hệ thống",
        "Modifier keys work best: they never insert a character when you hold them. Esc always cancels a dictation in progress.": "Phím bổ trợ hoạt động tốt nhất: giữ chúng không bao giờ chèn ký tự. Esc luôn hủy phiên đọc chính tả đang diễn ra.",
        "Reading “%@”…": "Đang đọc “%@”…",
        "Record this call?": "Ghi âm cuộc gọi này?",
        "Searching your meetings…": "Đang tìm trong các cuộc họp của bạn…",
        "Start Recording": "Bắt đầu ghi âm",
        "Tags": "Thẻ",
        "Voices": "Giọng nói",
        "Summary": "Tóm tắt",
        "Outline": "Dàn ý",
        "Hide outline": "Ẩn dàn ý",
        "Show outline": "Hiện dàn ý",
        "two levels": "hai cấp",
        "three levels": "ba cấp",
        "%d moments": "%d khoảnh khắc",
        "Kept on this Mac. Deleting is immediate; beyond 50 conversations the oldest age out.": "Lưu trên máy Mac này. Xóa có hiệu lực ngay; quá 50 cuộc trò chuyện thì cái cũ nhất bị loại.",
        "Ask across all meetings…": "Hỏi trong mọi cuộc họp…",
        "Recently Added": "Mới thêm gần đây",
        "%d meetings · %d h of audio": "%d cuộc họp · %d giờ âm thanh",
        "%d meetings · %d min of audio": "%d cuộc họp · %d phút âm thanh",
        "Show more": "Hiện thêm",
        "Try one of these": "Thử một trong số này",
        "Accessibility access is turned off": "Quyền Trợ năng đang tắt",
        "Dictation can hear you but cannot type. Re-enable it to continue.": "Đọc chính tả nghe được bạn nhưng không gõ được. Bật lại để tiếp tục.",
        "Recent dictations": "Chính tả gần đây",
        "Secure input is active — the hotkey cannot work": "Nhập an toàn đang bật — phím tắt không thể hoạt động",
        "Something has a password field focused. macOS does not say which app. Click into an ordinary text field and dictation works again.": "Ứng dụng nào đó đang đặt tiêu điểm ở ô mật khẩu. macOS không nói là ứng dụng nào. Bấm vào ô văn bản thường là chính tả hoạt động lại.",
        "Start Recording Meeting": "Ghi âm cuộc họp",
        "Stop Recording Meeting": "Dừng ghi âm cuộc họp",
        "click to copy": "bấm để sao chép",
        "dictate in %@": "đọc bằng %@",
        "dictate in any language": "đọc bằng bất kỳ ngôn ngữ nào",
        "translate %@ → %@": "dịch %@ → %@",
        "translate into %@": "dịch sang %@",
        "%d waiting": "%d đang chờ",
        "%d words typed": "Đã gõ %d từ",
        "Add a Key…": "Thêm khóa…",
        "Both will be inserted in the order you spoke them": "Cả hai sẽ được chèn theo thứ tự bạn đã nói",
        "Check Audio Setup": "Kiểm tra thiết lập âm thanh",
        "Clear All Filters": "Xóa mọi bộ lọc",
        "F-keys can also trigger a system control (brightness, media) — macOS will do both. To use one as a plain key, turn on “Use F1, F2, etc. as standard function keys” in Keyboard settings.": "Phím F cũng kích hoạt điều khiển hệ thống (độ sáng, phương tiện) — macOS sẽ làm cả hai. Để dùng như phím thường, bật «Use F1, F2, etc. as standard function keys» trong cài đặt bàn phím.",
        "How this works": "Cách hoạt động",
        "Input device changed": "Thiết bị đầu vào đã thay đổi",
        "Insert text by": "Chèn văn bản bằng",
        "It was revoked or replaced since you connected. It has been removed from the Keychain — nothing was retried with it.": "Nó đã bị thu hồi hoặc thay thế sau khi kết nối. Đã xóa khỏi Keychain — không thử lại gì với nó.",
        "Join a call in the browser, then start recording. Dictate captures your microphone and the call audio, transcribes both on this Mac, and keeps the transcript here. Nothing is uploaded.": "Tham gia cuộc gọi trong trình duyệt rồi bắt đầu ghi âm. Dictate thu micrô và âm thanh cuộc gọi, phiên âm cả hai trên máy Mac này và giữ bản ghi tại đây. Không tải lên bất cứ thứ gì.",
        "No meeting has all of these tags": "Không cuộc họp nào có tất cả các thẻ này",
        "No meeting has this tag": "Không cuộc họp nào có thẻ này",
        "Nothing was said, or nothing was heard": "Không ai nói gì, hoặc không nghe thấy gì",
        "Only the unconfirmed tail is shown here — the rest is already in the document": "Ở đây chỉ hiển thị phần đuôi chưa xác nhận — phần còn lại đã ở trong tài liệu",
        "Open Console": "Mở console",
        "Open Settings": "Mở Cài đặt",
        "Pasting is instant but replaces your clipboard for a moment. Typing works in apps that block paste, such as some terminals and remote desktops.": "Dán thì tức thời nhưng chiếm bảng nhớ tạm trong giây lát. Gõ hoạt động ở các ứng dụng chặn dán, như một số terminal và màn hình từ xa.",
        "Pasting it at once": "Dán một lần",
        "Recording ended here — this Mac went to sleep.": "Bản ghi kết thúc tại đây — máy Mac này đã ngủ.",
        "Remove “%@”": "Bỏ «%@»",
        "Return sends · Shift-Return adds a line · Esc clears": "Return gửi · Shift-Return xuống dòng · Esc xóa",
        "Show Floating Timer": "Hiện đồng hồ nổi",
        "Start Recording a Meeting": "Ghi âm cuộc họp",
        "Still recognizing the previous dictation": "Vẫn đang nhận dạng lần đọc trước",
        "Still recognizing the previous dictation · %d words": "Vẫn đang nhận dạng lần đọc trước · %d từ",
        "Switched to %@": "Đã chuyển sang %@",
        "Tag filters combine with “and” — a meeting must carry every selected tag to appear.": "Bộ lọc thẻ kết hợp bằng «và» — cuộc họp phải mang đủ mọi thẻ đã chọn.",
        "The answer stopped. Your question is kept above — retry when the connection returns. Search and transcripts still work.": "Câu trả lời đã dừng. Câu hỏi của bạn còn ở trên — thử lại khi có mạng. Tìm kiếm và bản ghi vẫn hoạt động.",
        "The recording ran, but no speech was recognized on either side. Usually this means the call audio was never captured — a browser tab without audio permission, or the wrong output device.": "Bản ghi đã chạy nhưng không nhận dạng được giọng nói ở bên nào. Thường nghĩa là âm thanh cuộc gọi chưa từng được thu — tab trình duyệt không có quyền âm thanh, hoặc sai thiết bị đầu ra.",
        "The saved key no longer works": "Khóa đã lưu không còn hoạt động",
        "The switch stays off until it is granted in System Settings › Privacy & Security › Calendars. Only event titles that overlap a recording are ever read.": "Công tắc sẽ tắt cho đến khi được cấp trong System Settings › Privacy & Security › Calendars. Chỉ đọc tiêu đề sự kiện trùng thời gian ghi.",
        "This Mac is offline": "Máy Mac này đang ngoại tuyến",
        "Too many questions at once": "Quá nhiều câu hỏi cùng lúc",
        "Typing as you speak": "Đang gõ khi bạn nói",
        "Typing into %@ as you speak": "Đang gõ vào %@ khi bạn nói",
        "Typing it out character by character": "Gõ từng ký tự",
        "Your provider account is out of credit": "Tài khoản nhà cung cấp của bạn hết tín dụng",
        "Your provider is rate limiting. Wait a few seconds and retry — nothing was lost.": "Nhà cung cấp đang giới hạn tần suất. Đợi vài giây rồi thử lại — không mất gì cả.",
        "macOS denied calendar access": "macOS đã từ chối quyền truy cập lịch",
        "API key": "Khóa API",
        "All Meetings": "Tất cả cuộc họp",
        "Assistant": "Trợ lý",
        "Checking the key with %@. No transcript is sent — only a test request.": "Đang kiểm tra khóa với %@. Không gửi bản ghi nào — chỉ một yêu cầu thử.",
        "Closing the window does not stop the recording. Stop it here, or from the menu bar at any time.": "Đóng cửa sổ không dừng ghi âm. Dừng tại đây hoặc từ thanh menu bất cứ lúc nào.",
        "Connect an assistant to answer questions": "Kết nối trợ lý để trả lời câu hỏi",
        "Dictate can record a browser call and keep the transcript on this Mac. Start one from the menu bar when your next call begins — you will be asked for consent once.": "Dictate có thể ghi âm cuộc gọi trên trình duyệt và giữ bản ghi trên máy Mac này. Bắt đầu từ thanh menu khi cuộc gọi tiếp theo diễn ra — sự đồng ý chỉ được hỏi một lần.",
        "Done": "Xong",
        "Every change takes effect immediately.": "Mọi thay đổi có hiệu lực ngay lập tức.",
        "Get one at %@.": "Lấy khóa tại %@.",
        "Hold a key, speak, let go. What you said is typed where your cursor is, in any app on this Mac.": "Giữ một phím, nói, rồi thả ra. Những gì bạn nói được gõ vào nơi con trỏ đang đứng, trong mọi ứng dụng trên máy Mac này.",
        "Keys": "Phím",
        "Languages": "Ngôn ngữ",
        "Library": "Thư viện",
        "Paste a key from your own account.": "Dán khóa từ tài khoản của chính bạn.",
        "Saved to your Keychain, but not verified — this Mac is offline. It will be checked the first time you ask something.": "Đã lưu vào Keychain nhưng chưa xác minh — máy Mac này đang ngoại tuyến. Sẽ kiểm tra khi bạn hỏi lần đầu.",
        "Set Up Dictate": "Thiết lập Dictate",
        "Stored in the macOS Keychain on this Mac. Never written to a settings file, never synced.": "Được lưu trong Keychain của macOS trên máy Mac này. Không bao giờ ghi vào tệp cài đặt, không bao giờ đồng bộ.",
        "The key was refused. It may be revoked, from a different provider, or out of credit — the key itself was not saved.": "Khóa bị từ chối. Có thể đã bị thu hồi, thuộc nhà cung cấp khác hoặc hết tín dụng — khóa chưa được lưu.",
        "Transcripts, search and quotes work without this. An assistant is only needed to write the answer.": "Bản ghi, tìm kiếm và trích dẫn hoạt động mà không cần điều này. Trợ lý chỉ cần để viết câu trả lời.",
        "Try Again": "Thử lại",
        "Updates": "Cập nhật",
        "You pay your provider per question — typically a fraction of a cent. Only your question and the quoted passages are sent; recordings never leave this Mac.": "Bạn trả phí cho nhà cung cấp theo từng câu hỏi — thường chỉ một phần xu. Chỉ câu hỏi và các đoạn trích được gửi đi; bản ghi âm không bao giờ rời khỏi máy Mac này.",
        "Send": "Gửi",
        "Conversations": "Cuộc trò chuyện",
        "New question": "Câu hỏi mới",
        "Deleted “%@”": "Đã xóa “%@”",
        "Undo": "Hoàn tác",
        "Questions you ask are kept here so you can return to an answer.": "Các câu hỏi được lưu ở đây để bạn quay lại câu trả lời.",
        "Rename": "Đổi tên",
        "Delete": "Xóa",
        "Voices are matched by sound — the name applies only to this voice's turns.": "Giọng nói được so khớp theo âm thanh — tên chỉ áp dụng cho lượt nói của giọng này.",
        "Call · voice %d": "Cuộc gọi · giọng %d",
        "Starred": "Đã gắn sao",
        "Other browser calls": "Cuộc gọi trình duyệt khác",
        "Sources": "Nguồn",
        "Star meeting": "Gắn sao",
        "Unstar meeting": "Bỏ gắn sao",
        "Export transcript…": "Xuất bản ghi…",
        "Still recording": "Vẫn đang ghi âm",
        "Got it": "Đã hiểu",
        "Call": "Cuộc gọi",
        "Dictating": "Đang đọc chính tả",
        "Dictating in %@": "Đang đọc chính tả bằng %@",
        "Translating into English": "Đang dịch sang tiếng Anh",
        "Translating into %@": "Đang dịch sang %@",
        "Release %@ to insert": "Thả %@ để chèn",
        "Also recording this meeting": "Cuộc họp này cũng đang được ghi âm",
        "%@ MB/s · about %@ left": "%@ MB/s · còn khoảng %@",
        "Not enough disk space: the download needs about %d MB and %d MB is free. Free up space and try again.": "Không đủ dung lượng đĩa: bản tải cần khoảng %d MB nhưng chỉ còn %d MB trống. Hãy giải phóng dung lượng rồi thử lại.",
        "Fix…": "Sửa…",
        "Checked automatically · last %@": "Kiểm tra tự động · lần cuối: %@",
        "Links": "Liên kết",
        "Source code": "Mã nguồn",
        "Report an issue": "Báo cáo sự cố",
        "Finishing the transcript…": "Đang hoàn tất bản ghi…",
        "Disk almost full — will stop to keep the transcript": "Đĩa sắp đầy — sẽ dừng để giữ bản ghi",
        "Dictate is running from its disk image": "Dictate đang chạy từ ảnh đĩa",
        "Permissions granted from a disk image are lost as soon as it is ejected, and the model would download again every time. Move Dictate to your Applications folder first.": "Quyền cấp từ ảnh đĩa sẽ mất ngay khi đẩy ra, và mô hình sẽ phải tải lại mỗi lần. Hãy chuyển Dictate vào thư mục Ứng dụng trước.",
        "Move to Applications": "Chuyển vào Ứng dụng",
        "Quit": "Thoát",
        "Couldn't move Dictate automatically": "Không thể tự động chuyển Dictate",
        "Drag Dictate from the disk image into the Applications folder, then launch it from there.": "Kéo Dictate từ ảnh đĩa vào thư mục Ứng dụng, rồi mở từ đó.",
        "OK": "OK",
        "Inserted into %@": "Đã chèn vào %@",
        "Inserted": "Đã chèn",
