        "Accessibility permission is off, so the key can't be heard. Turn it on in System Settings → Privacy & Security → Accessibility — Dictate picks it up automatically, no restart needed.": "Quyền Trợ năng đang tắt nên không nhận biết được phím. Hãy bật trong Cài đặt hệ thống → Quyền riêng tư & Bảo mật → Trợ năng — Dictate sẽ tự nhận ngay, không cần khởi động lại.",
