        "Tip: hold %@ instead — your speech comes out in English.": "Mẹo: giữ %@ thay vì phím thường — lời nói của bạn sẽ thành tiếng Anh.",
        "Hold to talk in your language, release to insert it in English.": "Giữ phím và nói bằng ngôn ngữ của bạn, thả ra — văn bản chèn vào bằng tiếng Anh.",
