        "Translation data": "Dữ liệu dịch",
        "The translate key transcribes your speech, then macOS translates it on this Mac. Picking a language may download its translation data once.": "Phím dịch phiên âm lời bạn nói, rồi macOS dịch ngay trên máy Mac này. Khi chọn ngôn ngữ, macOS có thể tải dữ liệu dịch một lần.",
        "Recognition runs on your Mac's Neural Engine — Whisper large-v3-turbo: 112 languages, great with accents, fast enough for live text. Translation runs on this Mac too. Your voice never leaves this computer.": "Nhận dạng chạy trên Neural Engine của máy Mac — Whisper large-v3-turbo: 112 ngôn ngữ, xử lý tốt giọng vùng miền và đủ nhanh để hiện văn bản trực tiếp. Việc dịch cũng diễn ra trên máy Mac này. Giọng nói của bạn không bao giờ rời khỏi máy tính này.",
        "Hold %@ and say it again — this time it comes out in %@.": "Giữ %@ và nói lại câu đó — lần này sẽ ra bằng %@.",
