    static let tl: [String: String] = [
        "Settings": "Mga Setting",
        "Keyboard shortcuts": "Mga keyboard shortcut",
        "Storage & models": "Storage at mga model",
        "Asking is the one thing that leaves this Mac: your question, the search hits, and the transcripts the agent opens to answer go to %@ on your key. Nothing is sent until you ask.": "Ang pagtatanong lang ang umaalis sa Mac na ito: ang tanong mo, ang mga tama sa paghahanap, at ang mga transcript na binubuksan ng agent para sumagot ay pumupunta sa %@ gamit ang key mo. Walang ipinapadala hangga't hindi ka nagtatanong.",
        "The Keychain refused to save the key — it stays in the field. Try again after unlocking the keychain.": "Tumanggi ang Keychain na i-save ang key — nanatili ito sa field. I-unlock ang keychain at subukan ulit.",
        "Couldn't reach the update server. Try again once you're online.": "Hindi maabot ang update server. Subukan ulit kapag online ka na.",
        "Update %@ is on its way — downloading now, it installs itself soon.": "Parating na ang update %@ — dina-download ngayon, mag-i-install ito mag-isa.",
        "You're up to date — Dictate %@ is the newest version.": "Updated ka na — ang Dictate %@ ang pinakabagong bersyon.",
        "Recorded meetings appear here.": "Dito lalabas ang mga na-record na meeting.",
        "This is your microphone only — the other side of the call was not recorded and cannot be recovered.": "Mikropono mo lang ito — ang kabilang panig ng tawag ay hindi na-record at hindi na maibabalik.",
        "Turning both on covers the calls that come next.": "Kapag binuksan pareho, sakop na ang mga susunod na tawag.",
        "%@ refused the request for billing reasons. Add credit in your provider account, or disconnect the agent in Settings.": "Tinanggihan ng %@ ang request dahil sa billing. Magdagdag ng credit sa provider account mo, o idiskonekta ang agent sa Settings.",
        "Agent": "Agent",
        "Ask your agent": "Tanungin ang agent",
        "Ask your agent anything…": "Itanong kahit ano sa agent mo…",
        "Has read %d of %d meetings": "Nabasa na ang %d sa %d meeting",
        "Has read 1 meeting": "Nabasa na ang 1 meeting",
        "Has read all %d meetings": "Nabasa na ang lahat ng %d meeting",
        "Meetings & Agent…": "Mga Meeting at Agent…",
        "Not now keeps the agent off and hidden. Search and transcripts are unaffected.": "Ang Hindi muna ay pananatilihing naka-off at nakatago ang agent. Hindi maaapektuhan ang paghahanap at mga transcript.",
        "Nothing to read yet": "Wala pang mababasa",
        "Off — has read nothing yet": "Naka-off — wala pang nabasa",
        "Questions are never limited to one meeting. Your agent searches everything you have recorded and the answer names the meeting and the person.": "Ang mga tanong ay hindi limitado sa isang meeting. Hinahanap ng agent mo ang lahat ng na-record mo at binabanggit ng sagot ang meeting at ang tao.",
        "Reading %d of %d meetings…": "Binabasa ang %d sa %d meeting…",
        "The agent uses": "Ginagamit ng agent",
        "This is what writes the summary and the outline, and what gives your agent something to answer from. Off, you get the raw transcript — no summary, no outline, and no agent. Nothing is sent anywhere either way.": "Ito ang sumusulat ng buod at balangkas, at nagbibigay sa agent mo ng masasagot. Kapag naka-off, hilaw na transcript lang — walang buod, walang balangkas, at walang agent. Anuman ang mangyari, walang ipinapadala kahit saan.",
        "Your agent answers questions across everything you have recorded — “what did we decide about the freeze date” — and cites the meeting and moment it came from. It needs the model that reads your meetings, which is currently off. Nothing leaves this Mac either way.": "Sinasagot ng agent mo ang mga tanong sa lahat ng na-record mo — “ano ang napagdesisyunan natin sa freeze date” — at binabanggit ang meeting at sandaling pinagmulan nito. Kailangan nito ang model na nagbabasa ng mga meeting mo, na naka-off ngayon. Anuman ang mangyari, walang umaalis sa Mac na ito.",
        "Your agent has nothing to read yet": "Wala pang mababasa ang agent mo",
        "Your agent has read 1 meeting": "Nabasa na ng agent mo ang 1 meeting",
        "Your agent has read all %d meetings": "Nabasa na ng agent mo ang lahat ng %d meeting",
        "Your agent is off": "Naka-off ang agent mo",
        "Your agent is reading — %d of %d meetings so far": "Nagbabasa ang agent mo — %d sa %d meeting sa ngayon",
        "answers with %@": "sumasagot gamit ang %@",
        "Nothing here can hear a call until it is granted in System Settings › Privacy & Security › Microphone.": "Walang makakarinig ng tawag dito hangga't hindi ito pinapayagan sa System Settings › Privacy & Security › Microphone.",
        "There is no summary or outline — reading your meetings is off.": "Walang buod o balangkas — naka-off ang pagbabasa ng mga meeting mo.",
        "This is your microphone only — the other side of the call is missing, the text is one unbroken block, and there is no summary or outline.": "Mikropono mo lang ito — wala ang kabilang panig ng tawag, iisang tuloy-tuloy na bloke ang teksto, at walang buod o balangkas.",
        "Turn both on": "Buksan pareho",
        "Turn it on": "Buksan ito",
        "Turning it on also writes them for the recordings that come next. Writing one now leaves the switch off.": "Kapag binuksan, maisusulat din ang mga ito para sa mga susunod na recording. Ang pagsulat ngayon ay mananatiling naka-off ang switch.",
        "Waiting on microphone access.": "Naghihintay ng access sa mikropono.",
        "Waits for “%@” above — there is no call audio to separate yet.": "Naghihintay sa “%@” sa itaas — wala pang audio ng tawag na paghihiwalayin.",
        "Write one, this once": "Sumulat ng isa, ngayon lang",
        "Writing one now reads only this transcript and leaves the switches off. The other side of this call was not recorded and cannot be recovered.": "Ang pagsulat ngayon ay babasahin lang ang transcript na ito at mananatiling naka-off ang mga switch. Ang kabilang panig ng tawag na ito ay hindi na-record at hindi na maibabalik.",
        "Writing…": "Sinusulat…",
        "macOS denied microphone access": "Tinanggihan ng macOS ang access sa mikropono",
        "%@ call — not being recorded": "Tawag sa %@ — hindi nire-record",
        "Asked once. After this, the panel is the short version above.": "Minsan lang itatanong. Pagkatapos nito, ang panel ay ang maikling bersyon sa itaas.",
        "Call recording is off, so this one is passing untranscribed. Turning it on gives you a searchable transcript and a summary afterwards, kept on this Mac.": "Naka-off ang pag-record ng tawag, kaya lilipas ito nang walang transcript. Kapag binuksan, magkakaroon ka pagkatapos ng transcript na mahahanap at buod, nakatago sa Mac na ito.",
        "Call — not being recorded": "Tawag — hindi nire-record",
        "Calls are not noticed automatically. You can start each one here, or let Dictate offer when a call begins.": "Hindi awtomatikong napapansin ang mga tawag. Maaari mong simulan ang bawat isa dito, o hayaang mag-alok ang Dictate kapag nagsimula ang tawag.",
        "Connect a provider…": "Ikonekta ang provider…",
        "Dictation still works. Each switch below says what it adds; you can turn on one and leave the rest alone.": "Gumagana pa rin ang dictation. Sinasabi ng bawat switch sa ibaba kung ano ang idinadagdag nito; maaari mong buksan ang isa at hayaan ang iba.",
        "Dictation works already — hold the dictation key and speak anywhere. Everything below is about meetings, and none of it is required. Turn on what you want; the rest stays off.": "Gumagana na ang dictation — pindutin nang matagal ang dictation key at magsalita kahit saan. Ang lahat sa ibaba ay tungkol sa mga meeting, at walang kinakailangan dito. Buksan ang gusto mo; mananatiling naka-off ang iba.",
        "Don't offer this again": "Huwag nang i-alok ulit",
        "Everything here is off, so calls pass unnoticed": "Naka-off ang lahat dito, kaya lumilipas ang mga tawag nang hindi napapansin",
        "Let the model read your meetings": "Hayaang basahin ng model ang mga meeting mo",
        "Not watching for calls": "Hindi nagbabantay sa mga tawag",
        "Notice when a call starts": "Pansinin kapag nagsimula ang tawag",
        "Off, a recording holds your microphone only — your half of the conversation, in one unbroken block. On, both sides are transcribed as named turns.": "Kapag naka-off, ang recording ay mikropono mo lang — ang kalahati mo ng usapan, sa iisang tuloy-tuloy na bloke. Kapag naka-on, parehong panig ang naitatala bilang may pangalang pagkakasunod.",
        "Off, you get only your own microphone — your half of the conversation. On, the other side is transcribed as well.": "Kapag naka-off, sarili mong mikropono lang — ang kalahati mo ng usapan. Kapag naka-on, naitatala rin ang kabilang panig.",
        "On": "Naka-on",
        "Or leave this and set them up later in Settings.": "O iwanan ito at i-set up mamaya sa Settings.",
        "Read meeting names from Calendar": "Basahin ang pangalan ng meeting mula sa Calendar",
        "Record the call audio too": "I-record din ang audio ng tawag",
        "Record the call audio, and separate the voices": "I-record ang audio ng tawag, at paghiwalayin ang mga boses",
        "Recordings arrive already titled instead of as “Zoom call, 14:02”. Only titles overlapping a recording are read.": "Dumarating ang mga recording na may pamagat na, sa halip na “Zoom call, 14:02”. Tanging mga pamagat na tumatapat sa recording ang binabasa.",
        "Separate the voices": "Paghiwalayin ang mga boses",
        "Set up calls…": "I-set up ang mga tawag…",
        "The agent searches and reads your transcripts on this Mac; the written answer comes from a provider you connect with your own key.": "Naghahanap at nagbabasa ang agent ng mga transcript mo sa Mac na ito; ang nakasulat na sagot ay galing sa provider na ikinonekta mo gamit ang sarili mong key.",
        "Three things are off. Here is what each one adds.": "Tatlong bagay ang naka-off. Narito kung ano ang idinadagdag ng bawat isa.",
