        "Turns one block of text into named turns, so you can see who committed to what. Names are yours to set and can be changed after the fact.": "Ginagawa nitong may pangalang pagkakasunod ang iisang bloke ng teksto, para makita kung sino ang nangako ng ano. Ikaw ang magtatakda ng mga pangalan at maaaring baguhin pagkatapos.",
        "Watching for calls": "Nagbabantay sa mga tawag",
