        "Hold to talk, release to insert what you said.": "I-hold para magsalita, bitawan para ilagay ang sinabi mo.",
        "Version": "Bersyon",
        "Downloaded %d of %d MB": "Na-download na ang %d sa %d MB",
        "Preparing the model for the Neural Engine… A few minutes, one time.": "Inihahanda ang model para sa Neural Engine… Ilang minuto, isang beses lang.",
        "Warming up the model…": "Nagwa-warm up ang model…",
        "Dictate is running from the downloaded image — drag it into Applications, eject the image, and launch it from there. Permissions granted to this temporary copy won't stick.": "Tumatakbo ang Dictate mula sa na-download na image — i-drag ito sa «Applications», i-eject ang image, at buksan mula roon. Hindi mananatili ang mga permisong ibinigay sa pansamantalang kopyang ito.",
        "Still stuck? Reset the permission — this clears the broken macOS record, then grant the fresh request.": "Stuck pa rin? I-reset ang permission — buburahin nito ang sirang record ng macOS, pagkatapos ay ibigay itong muli sa bagong dialog.",
        "Words: %d · %.1f s": "Mga salita: %d · %.1f s",
        "Words: %d": "Mga salita: %d",
        "Cancelled": "Kinansela",
        "Changed your mind? Esc cancels the recording.": "Nagbago ang isip mo? Kinakansela ng Esc ang recording.",
        "Network access: a one-time model download — nothing else. Don't take our word for it: turn off Wi-Fi and dictate.": "Network access: isang beses na pag-download ng model — wala nang iba. Huwag basta maniwala sa amin: i-off ang Wi-Fi at mag-dictate.",
        "About Dictate": "Tungkol sa Dictate",
        // Onboarding — general
        "Welcome to Dictate": "Maligayang pagdating sa Dictate",
        "Back": "Bumalik",
        "Next": "Susunod",
        "Step %d of %d": "Hakbang %d ng %d",
        // Welcome
        // Hotkey
        "Dictation key": "Dictation key",
        "This key types characters — they'll end up in your text while you hold it. A modifier (Option, Cmd, Shift, Ctrl) or an F-key is safer.": "Nagta-type ng characters ang key na ito — mapupunta ang mga ito sa text mo habang naka-hold. Mas ligtas ang modifier (Option, Cmd, Shift, Ctrl) o F-key.",
        // Permissions
        "Microphone": "Microphone",
        "Accessibility": "Accessibility",
        // Settings
        "Dictate Settings": "Mga Setting ng Dictate",
        "This key types characters — they'll go into the text during dictation. A modifier or F-key is better.": "Nagta-type ng characters ang key na ito — mapupunta ang mga ito sa text habang nagdi-dictate. Mas mainam ang modifier o F-key.",
        "Launch at login": "I-launch sa pag-log in",
        "Show in Dock": "Ipakita sa Dock",
        "The agent searches and reads your transcripts on this Mac, and every answer names the meetings it drew from.": "Naghahanap at nagbabasa ang agent ng iyong mga transcript sa Mac na ito, at pinapangalanan ng bawat sagot ang mga meeting na pinagbatayan.",
        "Undo remove": "I-undo ang pagtanggal",
        "Call started": "Nagsimula ang tawag",
        "Recording stopped by itself — the call ended.": "Huminto ang pag-record nang kusa — natapos ang tawag.",
        "Recording stopped by itself — ten minutes of silence.": "Huminto ang pag-record nang kusa — sampung minuto ng katahimikan.",
        "%@ call started": "Nagsimula ang tawag sa %@",
        "Not this one": "Hindi ito",
        "Record": "I-record",
        "Record this call": "I-record ang tawag na ito",
        "Dictation that works offline — recognition runs entirely on this Mac.": "Dictation na gumagana offline — ang pagkilala ay ganap na nangyayari sa Mac na ito.",
        "Translation that works offline — speak your language, another comes out.": "Pagsasalin na gumagana offline — magsalita sa iyong wika, ibang wika ang lalabas.",
        "Meetings, recorded and structured: speakers, summary, outline, search.": "Mga meeting na naitala at nakaayos: mga nagsalita, buod, outline, paghahanap.",
        "An optional agent that knows your meetings — answers quote the moment they came from.": "Opsyonal na agent na kilala ang iyong mga meeting — sinisipi ng mga sagot ang sandaling pinagmulan.",
        "%d MB of %d MB": "%d MB sa %d MB",
        "Already clicked and nothing changed?": "Nag-click ka pero walang nagbago?",
        "Applications": "Applications",
        "Downloading the speech model": "Dina-download ang speech model",
        "Grant…": "Ibigay…",
        "Nothing here leaves this window. Two small things to try, then you are done.": "Walang umaalis sa window na ito. Dalawang maliit na subukan, tapos ka na.",
        "Resume Download": "Ipagpatuloy ang download",
        "Show me where to look": "Ituro kung saan titingnan",
        "Start Dictate when I log in — it appears in the Dock and the menu bar, and the Dock icon can be hidden later in Settings": "Simulan ang Dictate kapag nag-log in ako — lalabas ito sa Dock at menu bar; maaaring itago ang Dock icon mamaya sa Settings",
        "Start Using Dictate": "Simulan ang paggamit ng Dictate",
        "Stopped · %d MB of %d MB kept on disk": "Huminto · %d MB sa %d MB ang nakatago sa disk",
        "The connection was interrupted. Resuming continues from where it stopped — you will not download the whole %d MB again.": "Naputol ang koneksyon. Ang pagpapatuloy ay magsisimula kung saan ito huminto — hindi mo ida-download muli ang buong %d MB.",
        "The download stopped at %d MB": "Huminto ang download sa %d MB",
        "The model is being compiled for your chip so recognition is fast later. This takes a minute on first launch and never happens again.": "Kinokompile ang model para sa iyong chip para mabilis ang pagkilala mamaya. Aabutin ng isang minuto sa unang paglunsad at hinding-hindi na mauulit.",
        "This happens once. The model stays on your Mac and is the reason dictation works without an internet connection afterwards.": "Isang beses lang ito nangyayari. Nananatili ang model sa iyong Mac — kaya gumagana ang dictation pagkatapos nang walang internet.",
        "To hear you. Audio is processed on this Mac and discarded.": "Para marinig ka. Pinoproseso ang audio sa Mac na ito at itinatapon.",
        "To type the recognized text into the app you are using. It is the only way an app can insert text elsewhere.": "Para i-type ang nakilalang teksto sa app na ginagamit mo. Ito lang ang paraan para makapagpasok ng teksto ang isang app sa iba.",
        "Try it here first": "Subukan muna rito",
        "Two permissions from macOS": "Dalawang pahintulot mula sa macOS",
        "macOS asks for these, not us. Dictate cannot work without both.": "Ang macOS ang humihingi ng mga ito, hindi kami. Hindi gagana ang Dictate nang wala ang pareho.",
        "Show or hide the conversations": "Ipakita o itago ang mga pag-uusap",
        "Show or hide the sidebar": "Ipakita o itago ang sidebar",
        "Show or hide the meeting list": "Ipakita o itago ang listahan ng meeting",
        "Preparing the model for this Mac": "Inihahanda ang model para sa Mac na ito",
        "Not ready yet — this takes a few seconds after launch. Keep holding %@ and it will start.": "Hindi pa handa — inaabot ng ilang segundo pagkatapos mag-launch. Pindutin nang matagal ang %@ at magsisimula ito.",
        "Transcript text": "Teksto ng transcript",
        "Smaller text": "Mas maliit na teksto",
        "Standard text": "Karaniwang teksto",
        "Larger text": "Mas malaking teksto",
        "112 languages · from your system settings": "112 wika · mula sa mga setting ng system",
        "Add tag": "Magdagdag ng tag",
        "Appearance": "Itsura",
        "Asked once. After this, recording starts from the menu bar without a prompt. Esc means don't record.": "Isang beses lang itatanong. Pagkatapos, magsisimula ang pag-record mula sa menu bar nang walang tanong. Ang Esc ay nangangahulugang huwag i-record.",
        "Check for updates": "Tingnan kung may update",
        "Choose your keys and languages": "Piliin ang iyong mga key at wika",
        "Click, then press a key": "I-click, pagkatapos ay pindutin ang isang key",
        "Dark": "Madilim",
        "Dictate stays dark even when macOS switches. Every surface follows: the window, the dictation overlay, the recording pill and the menu.": "Nananatiling madilim ang Dictate kahit magpalit ang macOS. Sumusunod ang lahat ng bahagi: ang window, ang dictation overlay, ang recording pill at ang menu.",
        "Dictate stays light even when macOS switches. Every surface follows: the window, the dictation overlay, the recording pill and the menu.": "Nananatiling maliwanag ang Dictate kahit magpalit ang macOS. Sumusunod ang lahat ng bahagi: ang window, ang dictation overlay, ang recording pill at ang menu.",
        "Dictate will record your microphone and the audio from the call, and keep the transcript on this Mac. Recording other people may require their consent where you are.": "Ire-record ng Dictate ang iyong mikropono at ang audio ng tawag, at itatago ang transcript sa Mac na ito. Ang pag-record sa ibang tao ay maaaring mangailangan ng kanilang pahintulot kung saan ka naroroon.",
        "Don't Record": "Huwag i-record",
        "Follows the macOS setting, switching with it at sunset. Choose Light or Dark to hold Dictate to one appearance regardless of the system.": "Sumusunod sa setting ng macOS at nagpapalit kasabay nito sa paglubog ng araw. Piliin ang Maliwanag o Madilim para manatili ang itsura ng Dictate anuman ang system.",
        "Hold the key while you speak. Anything can be changed later in Settings.": "Pindutin nang matagal ang key habang nagsasalita. Lahat ay maaaring baguhin mamaya sa Settings.",
        "I speak": "Nagsasalita ako ng",
        "Light": "Maliwanag",
        "Looking through %d meetings…": "Tinitingnan ang %d na meeting…",
        "Match system": "Sundan ang system",
        "Modifier keys work best: they never insert a character when you hold them. Esc always cancels a dictation in progress.": "Pinakamainam ang mga modifier key: hindi sila naglalagay ng character kapag pinindot nang matagal. Laging kinakansela ng Esc ang kasalukuyang dictation.",
        "Reading “%@”…": "Binabasa ang “%@”…",
        "Record this call?": "I-record ang tawag na ito?",
        "Searching your meetings…": "Hinahanap sa iyong mga meeting…",
        "Start Recording": "Simulan ang pag-record",
        "Tags": "Mga tag",
        "Voices": "Mga boses",
        "Summary": "Buod",
        "Outline": "Balangkas",
        "Hide outline": "Itago ang balangkas",
        "Show outline": "Ipakita ang balangkas",
        "two levels": "dalawang antas",
        "three levels": "tatlong antas",
        "%d moments": "%d sandali",
        "Kept on this Mac. Deleting is immediate; beyond 50 conversations the oldest age out.": "Nakatago sa Mac na ito. Agad ang pagbura; lampas sa 50 na usapan, natatanggal ang pinakaluma.",
        "Ask across all meetings…": "Magtanong sa lahat ng meeting…",
        "Recently Added": "Kamakailang Idinagdag",
        "%d meetings · %d h of audio": "%d meeting · %d oras ng audio",
        "%d meetings · %d min of audio": "%d meeting · %d minuto ng audio",
        "Show more": "Ipakita pa",
        "Try one of these": "Subukan ang isa sa mga ito",
        "Accessibility access is turned off": "Naka-off ang Accessibility access",
        "Dictation can hear you but cannot type. Re-enable it to continue.": "Naririnig ka ng dictation pero hindi makapag-type. I-enable muli para magpatuloy.",
        "Recent dictations": "Mga kamakailang diktasyon",
        "Secure input is active — the hotkey cannot work": "Aktibo ang secure input — hindi gagana ang hotkey",
        "Something has a password field focused. macOS does not say which app. Click into an ordinary text field and dictation works again.": "May app na naka-focus sa password field. Hindi sinasabi ng macOS kung alin. Mag-click sa karaniwang text field at gagana muli ang dictation.",
        "Start Recording Meeting": "Mag-record ng Meeting",
        "Stop Recording Meeting": "Ihinto ang Pag-record ng Meeting",
        "click to copy": "i-click para kopyahin",
        "dictate in %@": "mag-dikta sa %@",
        "dictate in any language": "mag-dikta sa kahit anong wika",
        "translate %@ → %@": "isalin %@ → %@",
        "translate into %@": "isalin sa %@",
        "%d waiting": "%d ang naghihintay",
        "%d words typed": "%d salita ang na-type",
        "Add a Key…": "Magdagdag ng Key…",
        "Both will be inserted in the order you spoke them": "Pareho silang ilalagay sa pagkakasunod ng pagsabi mo",
        "Check Audio Setup": "Suriin ang Audio Setup",
        "Clear All Filters": "Alisin ang Lahat ng Filter",
        "F-keys can also trigger a system control (brightness, media) — macOS will do both. To use one as a plain key, turn on “Use F1, F2, etc. as standard function keys” in Keyboard settings.": "Ang mga F-key ay nagpapagana rin ng system control (brightness, media) — gagawin ng macOS ang pareho. Para gamitin bilang karaniwang key, i-on ang «Use F1, F2, etc. as standard function keys» sa keyboard settings.",
        "How this works": "Paano ito gumagana",
        "Input device changed": "Nagbago ang input device",
        "Insert text by": "Ilagay ang teksto sa pamamagitan ng",
        "It was revoked or replaced since you connected. It has been removed from the Keychain — nothing was retried with it.": "Binawi o pinalitan na ito mula nang kumonekta ka. Inalis na ito sa Keychain — walang in-ulit gamit ito.",
        "Join a call in the browser, then start recording. Dictate captures your microphone and the call audio, transcribes both on this Mac, and keeps the transcript here. Nothing is uploaded.": "Sumali sa tawag sa browser, saka simulan ang pag-record. Kinukuha ng Dictate ang mikropono mo at audio ng tawag, tina-transcribe pareho sa Mac na ito, at itinatago rito ang transcript. Walang ina-upload.",
        "No meeting has all of these tags": "Walang meeting na may lahat ng tag na ito",
        "No meeting has this tag": "Walang meeting na may tag na ito",
        "Nothing was said, or nothing was heard": "Walang sinabi, o walang narinig",
        "Only the unconfirmed tail is shown here — the rest is already in the document": "Ang hindi pa kumpirmadong dulo lang ang makikita rito — ang iba ay nasa dokumento na",
        "Open Console": "Buksan ang Console",
        "Open Settings": "Buksan ang Settings",
        "Pasting is instant but replaces your clipboard for a moment. Typing works in apps that block paste, such as some terminals and remote desktops.": "Mabilis ang pag-paste pero pansamantalang pinapalitan ang clipboard. Gumagana ang pag-type sa mga app na humaharang sa paste, gaya ng ilang terminal at remote desktop.",
        "Pasting it at once": "Pag-paste nang isahan",
        "Recording ended here — this Mac went to sleep.": "Natapos ang recording dito — natulog ang Mac na ito.",
        "Remove “%@”": "Alisin ang «%@»",
        "Return sends · Shift-Return adds a line · Esc clears": "Return para ipadala · Shift-Return para sa bagong linya · Esc para burahin",
        "Show Floating Timer": "Ipakita ang Floating Timer",
        "Start Recording a Meeting": "Mag-record ng Meeting",
        "Still recognizing the previous dictation": "Kinikilala pa ang naunang diktasyon",
        "Still recognizing the previous dictation · %d words": "Kinikilala pa ang naunang diktasyon · %d salita",
        "Switched to %@": "Lumipat sa %@",
        "Tag filters combine with “and” — a meeting must carry every selected tag to appear.": "Pinagsasama ang mga tag filter gamit ang «at» — dapat taglay ng meeting ang bawat piniling tag.",
        "The answer stopped. Your question is kept above — retry when the connection returns. Search and transcripts still work.": "Huminto ang sagot. Nasa itaas pa rin ang tanong mo — subukan muli kapag bumalik ang koneksyon. Gumagana pa rin ang paghahanap at mga transcript.",
        "The recording ran, but no speech was recognized on either side. Usually this means the call audio was never captured — a browser tab without audio permission, or the wrong output device.": "Tumakbo ang recording pero walang nakilalang boses sa magkabilang panig. Kadalasan ibig sabihin ay hindi nakuha ang audio ng tawag — browser tab na walang audio permission, o maling output device.",
        "The saved key no longer works": "Hindi na gumagana ang naka-save na key",
        "The switch stays off until it is granted in System Settings › Privacy & Security › Calendars. Only event titles that overlap a recording are ever read.": "Mananatiling naka-off ang switch hanggang payagan sa System Settings › Privacy & Security › Calendars. Mga pamagat lang ng event na tumatapat sa recording ang binabasa.",
        "This Mac is offline": "Offline ang Mac na ito",
        "Too many questions at once": "Sobrang daming tanong nang sabay-sabay",
        "Typing as you speak": "Nagta-type habang nagsasalita ka",
        "Typing into %@ as you speak": "Nagta-type sa %@ habang nagsasalita ka",
        "Typing it out character by character": "Pag-type nang paisa-isang titik",
        "Your provider account is out of credit": "Ubos na ang credit ng account ng provider mo",
        "Your provider is rate limiting. Wait a few seconds and retry — nothing was lost.": "Nililimitahan ng provider mo ang dalas. Maghintay ng ilang segundo at subukan muli — walang nawala.",
        "macOS denied calendar access": "Tinanggihan ng macOS ang access sa kalendaryo",
        "API key": "API key",
        "All Meetings": "Lahat ng Meeting",
        "Assistant": "Assistant",
        "Checking the key with %@. No transcript is sent — only a test request.": "Sinusuri ang key sa %@. Walang transcript na ipinapadala — isang test request lang.",
        "Closing the window does not stop the recording. Stop it here, or from the menu bar at any time.": "Hindi hihinto ang pag-record kapag isinara ang window. Ihinto ito rito o mula sa menu bar anumang oras.",
        "Connect an assistant to answer questions": "Ikonekta ang assistant para sagutin ang mga tanong",
        "Dictate can record a browser call and keep the transcript on this Mac. Start one from the menu bar when your next call begins — you will be asked for consent once.": "Kayang i-record ng Dictate ang tawag sa browser at itago ang transcript sa Mac na ito. Simulan mula sa menu bar kapag nagsimula ang susunod mong tawag — isang beses lang hihingin ang pahintulot.",
        "Done": "Tapos na",
        "Every change takes effect immediately.": "Agad na nagkakabisa ang bawat pagbabago.",
        "Get one at %@.": "Kumuha sa %@.",
        "Hold a key, speak, let go. What you said is typed where your cursor is, in any app on this Mac.": "Pindutin nang matagal ang key, magsalita, bitawan. Ang sinabi mo ay itina-type kung nasaan ang cursor, sa kahit anong app sa Mac na ito.",
        "Keys": "Mga Key",
        "Languages": "Mga Wika",
        "Library": "Library",
        "Paste a key from your own account.": "I-paste ang key mula sa sarili mong account.",
        "Saved to your Keychain, but not verified — this Mac is offline. It will be checked the first time you ask something.": "Na-save sa iyong Keychain pero hindi pa na-verify — offline ang Mac na ito. Susuriin sa unang tanong mo.",
        "Set Up Dictate": "I-set Up ang Dictate",
        "Stored in the macOS Keychain on this Mac. Never written to a settings file, never synced.": "Nakaimbak sa macOS Keychain sa Mac na ito. Hindi kailanman isinusulat sa settings file, hindi kailanman sini-sync.",
        "The key was refused. It may be revoked, from a different provider, or out of credit — the key itself was not saved.": "Tinanggihan ang key. Maaaring bawi na ito, mula sa ibang provider, o ubos na ang credit — hindi na-save ang key.",
        "Transcripts, search and quotes work without this. An assistant is only needed to write the answer.": "Gumagana ang mga transcript, paghahanap at quote nang wala nito. Kailangan lang ang assistant para isulat ang sagot.",
        "Try Again": "Subukan Muli",
        "Updates": "Mga Update",
        "You pay your provider per question — typically a fraction of a cent. Only your question and the quoted passages are sent; recordings never leave this Mac.": "Nagbabayad ka sa provider mo kada tanong — kadalasan ay bahagi lang ng isang sentimo. Ang tanong mo at mga siniping sipi lang ang ipinapadala; hindi kailanman aalis ang mga recording sa Mac na ito.",
        "Send": "Ipadala",
        "Conversations": "Mga Usapan",
        "New question": "Bagong tanong",
        "Deleted “%@”": "Tinanggal ang “%@”",
        "Undo": "I-undo",
        "Questions you ask are kept here so you can return to an answer.": "Naka-imbak dito ang mga tanong para mabalikan ang sagot.",
        "Rename": "Palitan ang pangalan",
        "Delete": "Tanggalin",
        "Voices are matched by sound — the name applies only to this voice's turns.": "Tinutugma ang mga boses sa tunog — ang pangalan ay para lang sa mga linya ng boses na ito.",
        "Call · voice %d": "Tawag · boses %d",
        "Starred": "Naka-star",
        "Other browser calls": "Iba pang browser na tawag",
        "Sources": "Mga Source",
        "Star meeting": "I-star ang meeting",
        "Unstar meeting": "Alisin ang star",
        "Export transcript…": "I-export ang transcript…",
        "Still recording": "Nagre-record pa rin",
        "Got it": "Sige",
        "Call": "Tawag",
        "Dictating": "Nagdidikta",
        "Dictating in %@": "Nagdidikta sa %@",
        "Translating into English": "Isinasalin sa Ingles",
        "Translating into %@": "Isinasalin sa %@",
        "Release %@ to insert": "Bitawan ang %@ para ipasok",
        "Also recording this meeting": "Nire-record din ang meeting na ito",
        "%@ MB/s · about %@ left": "%@ MB/s · humigit-kumulang %@ na lang",
        "Not enough disk space: the download needs about %d MB and %d MB is free. Free up space and try again.": "Kulang ang espasyo sa disk: kailangan ng download ng humigit-kumulang %d MB at %d MB lang ang libre. Magbakante ng espasyo at subukan ulit.",
        "Fix…": "Ayusin…",
        "Checked automatically · last %@": "Awtomatikong sinusuri · huli: %@",
        "Links": "Mga Link",
        "Source code": "Source code",
        "Report an issue": "Mag-ulat ng problema",
        "Finishing the transcript…": "Tinatapos ang transcript…",
        "Disk almost full — will stop to keep the transcript": "Halos puno na ang disk — hihinto para mapanatili ang transcript",
        "Dictate is running from its disk image": "Tumatakbo ang Dictate mula sa disk image nito",
        "Permissions granted from a disk image are lost as soon as it is ejected, and the model would download again every time. Move Dictate to your Applications folder first.": "Ang mga pahintulot mula sa disk image ay nawawala sa sandaling i-eject ito, at muling dada-download ang model bawat beses. Ilipat muna ang Dictate sa Applications folder.",
        "Move to Applications": "Ilipat sa Applications",
        "Quit": "Umalis",
        "Couldn't move Dictate automatically": "Hindi awtomatikong mailipat ang Dictate",
        "Drag Dictate from the disk image into the Applications folder, then launch it from there.": "I-drag ang Dictate mula sa disk image papunta sa Applications folder, saka buksan mula roon.",
        "OK": "OK",
        "Inserted into %@": "Naipasok sa %@",
        "Inserted": "Naipasok",
        "Accessibility is off — dictation can hear you but cannot type": "Naka-off ang Accessibility — naririnig ka ng dictation pero hindi makapag-type",
        "Open Privacy & Security…": "Buksan ang Privacy & Security…",
        "1 dictation still being recognized": "1 dictation ang kinikilala pa",
        "%d dictations still being recognized": "%d dictation ang kinikilala pa",
        "Language Packs…": "Mga language pack…",
        "With this off, Dictate is menu-bar only. Clicking the Dock icon opens Meetings; the menu bar item is always there either way.":
            "Kapag naka-off, nasa menu bar lang ang Dictate. Ang pag-click sa Dock icon ay nagbubukas ng Mga Meeting; laging nariyan ang icon sa menu bar.",
        "Language": "Wika",
        "Interface language": "Wika ng interface",
        "Granted": "Naibigay",
        "No": "Hindi",
        "Model ready": "Handa na ang model",
        "On-device recognition": "On-device recognition",
        "Spoken language": "Wikang sinasalita",
        "Download failed. Check your connection and retry.": "Hindi natuloy ang download. I-check ang connection mo at subukan ulit.",
        "Not set": "Hindi nakatakda",
        "Remove": "Alisin",
        "Download & continue": "I-download at magpatuloy",
        "About %@ — downloaded once. This is the only time Dictate needs the internet.": "Mga %@ — isang beses lang ida-download. Ito lang ang pagkakataong kailangan ng Dictate ng internet.",
        "Hold %@ and say something — the recognized text shows up below.": "I-hold ang %@ at magsabi ng kahit ano — lalabas sa ibaba ang na-recognize na text.",
        "Recognized text appears here…": "Dito lalabas ang na-recognize na text…",
        // Menu bar
        "Settings…": "Mga Setting…",
        "Quit Dictate": "I-quit ang Dictate",
        "Dictate — voice dictation": "Dictate — voice dictation",
        // HUD
        "Recognizing…": "Nire-recognize…",
        "Esc to cancel": "Esc para kanselahin",
        // Errors
        "Couldn't start recording: %@": "Hindi masimulan ang recording: %@",
        "Recording truncated at %d seconds (limit)": "Naputol ang recording sa %d segundo (limit)",
        "Audio device changed during recording — recording cancelled, please try again.": "Nagbago ang audio device habang nagre-record — kinansela ang recording, subukan ulit.",
        "Accessibility permission is off, so the key can't be heard. Turn it on in System Settings → Privacy & Security → Accessibility — Dictate picks it up automatically, no restart needed.": "Naka-off ang Accessibility permission, kaya hindi maririnig ang key. I-on ito sa System Settings → Privacy & Security → Accessibility — awtomatiko itong makukuha ng Dictate, hindi na kailangang mag-restart.",
        "Microphone unavailable (no input audio format)": "Hindi magamit ang microphone (walang input audio format)",
